programs.luna:
"""Estimate a rare positive response for a single letter continuing a word or identifier."""
READS = ()

def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2:
        return None, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2]
    continues = bool(prev) and prev[-1].isalnum()
    if len(s) == 1 and s.isalpha() and continues:
        return None, 0.02
    return None, 0.0

programs.sol:
"""Approximate a delimiter, clause-joining and formal-diction response.

End-of-text is strongest. Clause punctuation boosts conjunctions; prose
semicolons differ from code terminators. Smaller responses use recognizable
word classes and English spelling endings, rather than token-ID tables.
Periods use counts between .!? punctuation, recent letter types, and long s.
Twenty recent tokens and a few counters are retained; each document resets them.
"""
READS = ()

LITERARY_ADVERBS = frozenset('''
chiefly formerly wholly expressly materially remarkably exceedingly
scarcely utterly
'''.split())
FORMAL_ADVERBS = frozenset('''
accordingly sufficiently substantially continually thoroughly consequently
'''.split())
EVALUATIVE_ADJECTIVES = frozenset('''
necessary requisite impossible considerable desirable admirable remarkable
allowable accessible evident apparent probable peculiar absurd ridiculous
formidable dangerous fearful ignorant
'''.split())
FORMAL_PARTICIPLES = frozenset('''
rendered employed engaged appointed adopted executed intended informed
subjected preserved distinguished retired attended observed desired
furnished continued satisfied obliged
'''.split())
FORMAL_ACTIONS = frozenset('''
render employ employment engage intend inform preserve distinguish retire
attend observe desire furnish continue satisfy
'''.split())
RELATIVE_WORDS = frozenset('which who whose whom whatever whoever such'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, length, mean_length, long_s = (), 0, 0.0, 0.0
    else:
        _, recent, length, mean_length, long_s = carry
    token = prefix.token_strings[-1]
    previous = recent[-1].rstrip() if recent else ''
    clause = previous.endswith((',', ';'))
    prior_digit = bool(previous) and previous[-1].isdigit()
    stripped = token.strip()
    word = stripped.lower()
    value = -0.0045

    if token == '<|endoftext|>':
        value = 1.77
    elif 'ſ' in token:
        value += 0.47
    elif stripped == ';' and '\n' not in token:
        code = any(any(c in s for c in '=[]{}`_$\\') for s in recent)
        value += 0.044 if code else 0.115 if prior_digit else 0.315
    elif stripped == '&':
        value += 0.315 if clause else 0.155
    elif stripped in ('—', '–'):
        value += 0.04 if token.startswith(' ') else 0.13
    elif stripped == '.':
        # Sentence endings differ from short abbreviations and code dots.
        code = any(any(c in s for c in '=[]{}`_$\\') for s in recent)
        foreign = sum(any(c.isalpha() and not c.isascii() for c in s)
                      for s in recent) / max(1, len(recent))
        letter = bool(previous) and previous[-1].isalpha()
        value = (-0.021 + 0.071 * min(length, 80) / 80
                 + 0.027 * min(mean_length, 80) / 80
                 + 0.021 * letter - 0.010 * code + 0.018 * foreign
                 + 0.064 * min(long_s, 2.0))
    elif stripped == ',':
        value -= 0.01

    # Lexical rules apply only to spaced, ASCII alphabetic tokens.
    if token.startswith(' ') and word.isascii() and word.isalpha():
        if len(word) > 4 and word.endswith('ed'):
            value += 0.066
        if len(word) > 5 and word.endswith(('able', 'ible')):
            value += 0.06
        if word in LITERARY_ADVERBS:
            value += 0.57
        elif word in FORMAL_ADVERBS:
            value += 0.19
        elif word in {'nearly', 'entirely', 'pretty', 'considerably'}:
            value += 0.285
        elif word in {'often', 'usually', 'sometimes'}:
            value -= 0.14
        if word in EVALUATIVE_ADJECTIVES:
            value += 0.283
        if word in FORMAL_PARTICIPLES:
            value += 0.21
        if word in FORMAL_ACTIONS:
            value += 0.155
        if word in RELATIVE_WORDS:
            value -= 0.074
        if word in {'had', 'did', 'been', 'being', 'must', 'should'}:
            value -= 0.07
        if word in {'under', 'after', 'within', 'without', 'across'}:
            value -= 0.08
        if word in {'very', 'every', 'various', 'just', 'well'}:
            value -= 0.10

        if word == 'and':
            value += 0.275 if clause else 0.0
        elif word == 'or':
            value += 0.20 if clause else -0.04
        elif word == 'but':
            value += 0.025 if clause else -0.10
        elif word == 'yet':
            value += 0.43 if clause else 0.235
        elif word == 'nor':
            value += 0.18 if clause else 0.05
        elif word == 'though':
            value += 0.235 if clause else 0.045
        elif word == 'although':
            value += 0.11
        elif word == 'et' and clause:
            value += 0.175
        elif word in {'und', 'och'}:
            value += 0.21 if clause else -0.04
        elif word in {'y', 'e'} and clause:
            value += 0.08
        if word == 'which' and clause:
            value += 0.036
        elif word == 'that' and clause:
            value += 0.10

    if token.startswith(' ') and word == 'и':
        value += 0.21 if clause else -0.04

    if any(c in token for c in '.!?'):
        if length >= 8:
            mean_length = 0.5 * (mean_length + length)
        length = 0
    else:
        length += 1
    long_s = 0.97 * long_s + ('ſ' in token)
    return (doc, (recent + (token,))[-20:],
            length, mean_length, long_s), float(value)

"""Detect boundaries after capital initials and acronym fragments.

Stops, parentheses and other separators are positive, as are conjunctions and
linking words. Longer capital fragments and capitals inside mixed-case words
or code identifiers are weaker cues. Lowercase acronym continuations are
negative. Ordinary text is near zero. A completed initial retains a smaller
boundary response for one extra token. State resets between documents.
These class-level rules omit individual token-specific variation.
"""
READS = ()
LINKS = {
    'and': .79, 'or': .79, 'e': .79, 'et': .79, 'y': .79, 'и': .79,
    'is': .65, 'are': .40, 'was': .20, 'were': .20, 'be': .20,
    'of': .28, 'for': .28, 'to': .28, 'in': .28, 'on': .28,
    'from': .28, 'with': .28, 'by': .28,
}
PUNCTUATION = {
    ',': .89, ':': .75, ';': .56, '=': .89, '-': .66,
    '[': .60, '{': .60, ']': .54, '}': .54,
    '_': .55, '^': .55, '\\': .70, '/': .70,
    '+': .36, '*': .36, '"': .46, "'": .46, '`': .46,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    bare = token.strip()
    capitals = 0
    for char in reversed(previous):
        if not char.isalpha() or not char.isupper():
            break
        capitals += 1
    value = 0.0
    if capitals:
        scale = 1.0 if capitals <= 2 else .68 if capitals <= 4 else .45
        if not bare:
            value = (.47 if '\n' in token else .74 if len(token) == 1 else .18)
        elif any(c.isalpha() for c in bare):
            if token[:1].isspace():
                value = LINKS.get(bare, 0.0)
            elif bare[0] == '.':
                value = .15 if capitals == 1 else .30 if capitals == 2 else 0.0
            elif bare[0] in '([{':
                value = .35 if capitals <= 2 else .10
            elif bare.islower():
                value = -.04 if capitals == 1 else -.46
            elif bare.istitle():
                value = -.25
            else:
                value = -.05
        elif bare[0] == '.':
            value = 1.20 if capitals == 1 else .75 if capitals == 2 else .62
            if bare in {'.,', '.;'}:
                value += .38
            elif bare != '.' and not bare.startswith(('.)', '.:', '.\\')):
                value = .38
            if '\n' in token:
                value *= .32
            if previous.strip().startswith('.'):
                value += .35
        elif bare == '(':
            value = 1.03
        elif bare[0] == ')':
            value = (.28 if '\n' in token else .56 if bare != ')' else
                     1.07 if capitals == 1 else 1.29)
        else:
            value = PUNCTUATION.get(bare[0], 0.0 if bare[0].isalnum() else .30)
            if '\n' in token:
                value *= .60 if bare[0] == ':' else .40
        if value > 0:
            value *= scale
            if any(c.islower() for c in previous) or '°' in previous:
                value *= .30
            elif '_' in previous:
                value *= .60
    elif carry and carry[0] == doc and previous.strip() == '.' and carry[2]:
        # A just-completed initial or dotted abbreviation can still be followed
        # by another boundary, as in 'J. (' or 'U.S. and'.
        if not bare:
            value = .15
        elif bare.isdigit():
            value = .18
        elif bare == '(':
            value = .50
        elif token[:1].isspace():
            value = .65 * LINKS.get(bare, 0.0)
    return (doc, token, capitals), float(value)

programs.luna:
"""A weak cue for English past be: score 'was'/'were' after non-pronouns."""
READS = ()

EXCLUDED_PREVIOUS_WORDS = {
    "i", "you", "he", "she", "it", "we", "they",
    "this", "that", "these", "those", "there",
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, old_doc = carry if carry is not None else ("", doc)
    if doc != old_doc:
        previous = ""

    word = prefix.token_strings[-1].strip().casefold()
    previous_word = previous.strip().casefold()
    value = -0.43 if (
        word in {"was", "were"}
        and previous_word not in EXCLUDED_PREVIOUS_WORDS
    ) else 0.0
    return (prefix.token_strings[-1], doc), value

"""Mark comparative speed and a rapid decrease, not every rapid-sounding word.

The strongest examples are “grow(s) faster than” and “decreases rapidly”.
Use smaller average values for the common word “faster” and its following
“than”; use a large negative value for those specific change phrases.
"""

READS = ()
GROWING = {"grow", "grows", "growing"}
DECREASING = {"decrease", "decreases", "decreased", "decline", "declines"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    recent = []
    previous_positions = range(
        len(prefix.token_strings) - 2,
        max(-1, len(prefix.token_strings) - 7),
        -1,
    )
    for i in previous_positions:
        if prefix.document_ids[i] != prefix.document_ids[-1]:
            break
        recent.append(prefix.token_strings[i].strip().lower())

    if word == "faster":
        if any(previous in GROWING for previous in recent):
            return None, -0.70
        return None, -0.38

    if word == "rapidly" and any(previous in DECREASING for previous in recent):
        return None, -0.72

    if word == "than" and len(prefix.token_strings) > 1:
        if prefix.document_ids[-2] != prefix.document_ids[-1]:
            return None, 0.0
        if prefix.token_strings[-2].strip().lower() == "faster":
            return None, -0.25

    return None, 0.0

programs.sol:
"""Approximate an unfinished-syllable signal from the current token's spelling.

Short fragments ending in consonant clusters get negative values, particularly
when they stop just after a Latin-derived prefix. Common grammatical words and
familiar derivational/inflectional suffixes are spared. Chat boundary markers form a second, separate
negative response. This is a spelling heuristic, not a dictionary of tokens.
"""
from functools import lru_cache
import math
import unicodedata

READS = ()
FUNCTION_WORDS = frozenset('''and all off its own with will must both such much
this that them then than when what which from whom who whose our your their
have has had can could would should might shall not but for nor yet only
und des les der den das del los las el le la un une en et ou qui que
как так ваш наш под над при без из об от он они она оно или но и в с к'''.split())
ENDINGS = frozenset('''ing ings ant ants ent ents er ers est ist ists
en ens on ons or ors an ans al als'''.split())
# Onset-like clusters, plus uncommon word-final consonant combinations.
ONSETS = frozenset('''pl cl bl gl fl tr pr br cr dr fr gr vr kl hr sc gn nv nf
nc nm nr nj nb xh xc xp sm rw sp'''.split())
LATIN_PREFIXES = ('con', 'com', 'de', 're', 'dis', 'in', 'im', 'ex', 'en',
                  'un', 'sub', 'ob', 'ad', 'ab', 'pro', 'pre', 'over',
                  'under', 'endo', 'neuro', 'epi', 'gastro', 'inter', 'extra')
GERMAN_PREFIXES = ('ge', 'be', 'ver', 'ent', 'zer', 'er')
SLAVIC_PREFIXES = ('вы', 'по', 'за', 'про', 'при', 'пре', 'пере', 'раз',
                  'рас', 'воз', 'вос', 'от', 'об', 'под', 'над', 'из', 'ис')


def cut_prefix(word, prefixes, vowels):
    return any(word.startswith(p) and len(word) > len(p)
               and all(c not in vowels for c in word[len(p):])
               for p in prefixes)


@lru_cache(maxsize=65536)
def spelling_score(token):
    word = token.strip().lstrip('._/-\\')
    word = ''.join(c for c in unicodedata.normalize('NFD', word.lower())
                   if not unicodedata.combining(c))
    if not word.isalpha() or word in FUNCTION_WORDS or word in ENDINGS:
        return 0.0
    latin = all('LATIN' in unicodedata.name(c, '') for c in word)
    cyrillic = all('CYRILLIC' in unicodedata.name(c, '') for c in word)
    if not (latin or cyrillic):
        return 0.0
    vowels = 'aeiouy' if latin else 'аеёиоуыэюя'
    n_vowels = sum(c in vowels for c in word)
    tail = ''
    for c in reversed(word):
        if c in vowels:
            break
        tail = c + tail
    if cyrillic:
        if word == 'пр':
            return -1.04
        if word.endswith(('ж', 'щ')):
            return -0.40
        if cut_prefix(word, SLAVIC_PREFIXES, vowels):
            if len(tail) >= 2:
                return -0.95 if token[:1].isspace() else -0.45
            return -0.75 if word.startswith('вы') else -0.25
        if n_vowels == 0 and len(word) >= 2:
            return -0.65 if word.endswith(('р', 'в')) else -0.12
        if n_vowels == 1 and len(tail) >= 2 and not word.endswith('ь'):
            return -0.30
        return 0.0
    if word.endswith('qu'):
        if len(word) == 2:
            return -0.28
        return -0.75 if len(word) >= 4 else -0.12
    if word in {'int', 'uint', 'long', 'short', 'bool', 'char', 'void', 'func'}:
        return 0.0
    if word == 'const':
        return -0.65
    if word.startswith('mc') and n_vowels == 0 and len(word) >= 3:
        return -1.0 - 0.6 * (len(word) >= 4)
    if n_vowels == 0:
        return -0.08 if len(word) >= 3 else 0.0
    if cut_prefix(word, GERMAN_PREFIXES, vowels) and len(tail) >= 2:
        if tail[-2:] in ONSETS:
            return -1.20
        if tail.endswith('sch'):
            return -0.70
    cut = cut_prefix(word, LATIN_PREFIXES, vowels)
    onset = len(tail) >= 2 and tail[-2:] in ONSETS
    if cut:
        if onset:
            return -1.20 if len(tail) >= 3 else -0.85
        if word.startswith(('con', 'com')):
            return -0.90
        if word.startswith(('in', 'im')):
            return -0.55
        if word.startswith(('de', 're', 'pro', 'pre')):
            if word.startswith(('pro', 'pre')) and len(tail) == 1:
                return -0.55
            return -0.10 if len(tail) == 1 else -0.12
        # 'end' is a complete word rather than the prefix en- plus an onset.
        if word != 'end':
            return -0.50 if len(word) > 4 else -0.30
    if n_vowels <= 1 and len(tail) >= 2 and len(word) <= 7:
        if len(tail) >= 3 and word.endswith('s'):
            return 0.0
        if onset:
            return -0.85 if word[0] in vowels else -0.45
        if tail[-1] == tail[-2] and len(word) >= 3:
            if tail[-1] in 'cgmnr':
                return -0.50
            return -0.18 if word[0] in vowels else 0.0
        if word[0] in vowels:
            if tail[-2:] in {'nd', 'nt', 'ng', 'ns', 'ls', 'st', 'rs', 'rd', 'rt'}:
                return -0.05
            return -0.40 if tail[0] in 'mn' else -0.18
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    position = carry[1] + 1 if carry and carry[0] == document else 0
    token = prefix.token_strings[-1]
    if token == '<|im_start|>':
        value = (-1.982 if position == 0
                 else -1.05 - 0.20 * math.exp(-position / 16))
    elif token == '</tool_response>':
        value = -1.21
    elif token == '<tool_response>':
        value = -0.70
    elif token in ('<think>', '</think>'):
        value = -0.59 if token == '<think>' else -0.40
    elif token in ('<tool_call>', '</tool_call>', '<|im_end|>'):
        value = 0.09 - 1.1 / (position + 1)
    elif position == 1 and token in ('user', 'assistant', 'system'):
        value = -0.76
    else:
        value = spelling_score(token)
    return (document, position), float(value)

programs.luna:
"""Predict a small positive cue at likely noun-phrase starts."""

READS = ()
POSSESSIVES = {"my", "your", "his", "her", "our", "their"}


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, 0.0
    previous = prefix.token_strings[t - 1].strip().lower()
    current = prefix.token_strings[t].strip()
    if not current or not current[0].isalpha():
        return None, 0.0
    if previous == "the":
        return None, 0.20
    if previous in POSSESSIVES:
        return None, 0.06
    if previous == "same":
        return None, 0.10
    return None, 0.0

programs.sol:
"""A J/j detector, with multilingual phonetic relatives and formatting side cues.

The largest response is to J-initial words/fragments, including code identifiers.
Capitalization, short fragments, and path punctuation adjust the response. The
next unspaced alphabetic token inherits a small continuation response.
Other scripts supply approximate j/zh-like spelling cues, not a full phonetic
transcription. Isolated name/function characters get extra weight. Thinking/tool
tags and certain indentation gaps fire separately. State resets per document.
"""
READS = ()

# Common j-initial Mandarin characters (simplified and traditional).
MANDARIN_J = (
    '及级級即既几幾机機基鸡雞积積激急极極吉纪紀记記季计計继繼寄祭集辑輯济濟技'
    '家加假价價架夹夾甲贾賈嘉佳嫁驾駕稼见見件间間建检檢减減简簡剑劍坚堅尖肩'
    '江将將讲講姜疆降奖獎蒋蔣教叫交角较較焦娇嬌骄驕胶膠脚腳郊'
    '接节節结結姐解界届屆阶階街洁潔介捷借戒揭截杰傑竭劫'
    '进進今金近尽盡仅僅紧緊禁晋晉锦錦斤筋津'
    '经經京精境景警静靜敬竟竞競惊驚井晶镜鏡径徑净淨睛颈頸靖'
    '就九酒久旧舊究救纠糾舅臼局举舉据據句具居聚剧劇巨距拒俱惧懼菊橘'
    '卷倦捐娟眷决決绝絕觉覺爵掘军軍君均俊郡钧鈞菌'
)
# J/zh-initial surnames: name-like characters are stronger cues.
J_SURNAMES = '贾賈江姜蒋蔣姬吉季纪紀计計金景井焦朱'
J_FUNCTION_CHARS = '及即既就将將仅僅'
HANGUL_INITIALS = 'ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ'
HANGUL_VOWELS = 'ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ'
TAGS = {
    '<tool_call>': 1.59, '</tool_response>': 1.48,
    '<think>': .49, '</think>': .81,
    '<tool_response>': .36, '</tool_call>': .35,
}
PUNCTUATION = '.,/_-([{:"\'\\'


def token_response(token):
    text = token.strip()
    if token in TAGS:
        return TAGS[token]
    if not text:
        if token.startswith('\t') and ' ' in token:
            return {7: .75, 15: .49}.get(token.count(' '), .10)
        return .51 if token == ' ' * 8 else .005

    word = text.lstrip(PUNCTUATION)
    low = word.lower()
    lead = text[:len(text) - len(word)]
    value = .005
    if low.startswith('j'):
        value += 1.94 + .27 * word[0].isupper()
        if len(word) == 1:
            value += .16 + .30 * word[0].isupper()
        elif len(word) <= 3:
            value += .32 + .38 * word[0].isupper()
        if lead in ('/', '.'):
            value += .28 + 1.79 * (word == 'j')
        elif lead == '-':
            value += .54
        elif lead in ('(', '['):
            value += .15
        if low.startswith('javax'):
            value += 1.48
        elif low == 'java' and token.startswith(' ') and not lead:
            value += .98
        if len(word) > 3 and any(c.isupper() for c in word[1:]):
            value += .29
        if low in ('january', 'june', 'july', 'jul'):
            value = {'january': 1.95, 'june': 1.17,
                     'july': 1.0, 'jul': 1.1}[low]
        elif low == 'je':
            value -= .5
    elif 'j' in low:
        value += .88

    if any(c in MANDARIN_J for c in text):
        value += .25 + .45 * (len(text) == 1)
    if len(text) == 1 and text in J_SURNAMES:
        value += .7
    if len(text) == 1 and text in J_FUNCTION_CHARS:
        value += .5
    if any(c in '日约約跃躍' for c in text):
        value += .93
    for c in text:
        n = ord(c) - 0xAC00
        if 0 <= n < 11172:
            onset = HANGUL_INITIALS[n // 588]
            vowel = HANGUL_VOWELS[(n % 588) // 28]
            value += .07
            if onset in 'ㅈㅉ':  # Hangul jieut / ssangjieut
                value += .38
            elif onset in 'ㄱㄲㅋ' and vowel in 'ㅑㅒㅕㅖㅛㅠ':
                value += .50  # g/k before a palatalizing vowel
            break
    if any(c in 'жЖјЈ' for c in text):
        value += .36 + .42 * low.startswith(('ж', 'дж'))
        value += .64 * low.startswith('дж')
    if low.startswith(('я', 'ю')):
        value += .38
    if any(c in 'じジぢヂ' for c in text):
        value += .55 + .36 * (len(text) == 1)
        if len(text) == 2 and any(c in 'ゃゅょぇャュョェ' for c in text):
            value += 1.32
    if 'ج' in text:
        value += .64 + .31 * token.startswith(' ')
        value += .57 * text.startswith(('ج', 'الج'))
        value += 1.16 * (text in ('ج', 'الج'))
    if 'จ' in text:
        value += .83 + 1.10 * (text == 'จ')
    if any(c in 'जਜজ' for c in text):
