"""Estimate sparse activation from j-like spelling cues. J at a word's
start gets a larger prediction than an internal j; script and markup cues
get smaller, characteristic positive values.
"""
READS = ()

MANDARIN_J = frozenset("就惊井即絕绝")


def script_j(text):
    for char in text:
        if char in MANDARIN_J:
            return True
        offset = ord(char) - 0xAC00
        if 0 <= offset < 11172 and offset // 588 == 12:
            return True
    return False


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "tool_" in token:
        value = 1.5
    elif token in ("<think>", "</think>"):
        value = 0.75
    elif token and all(char.isspace() for char in token) and (
        "\t" in token or len(token) >= 6
    ):
        value = 0.7
    elif script_j(token):
        value = 1.7
    elif "j" in token.lower():
        start = token.lower().lstrip(" \t.,_-/\\'\"([{<").startswith("j")
        value = 2.2 if start else 0.85
    else:
        value = 0.02
    return None, value

