"""A lexical stock/share/investment signal, with negative activation.

Recognize the words themselves, even in nonfinancial uses (stock up,
sharing, or Chinese 一股 'a gust'). Strongest are stock and Chinese 股;
related ownership, investment and dividend words are weaker. A small
secondary response catches the spelling fragments 'ock' and 'sock'.
A few adjacent-word constructions also respond: shares of, investing
in, and per share. No document-wide topic is inferred. Strengths are
rounded training estimates; unrecognized tokens default to zero.
"""
READS = ()


def token_signal(token):
    word = token.strip().lstrip('._/-(').lower()
    if word == 'stock':
        if token[:1].isspace():
            return -3.7
        return -2.5 if token == 'stock' else -3.1
    if word == 'stocks':
        return -2.9 if token[:1].isspace() else -2.0
    if word in {'stocked', 'stocking'}:
        return -1.3
    if word in {'shares', 'shareholder', 'shareholders'}:
        return -1.75
    if word == 'share':
        return -1.1
    if word == 'sharing':
        return -0.55
    if word == 'shared':
        return -0.38
    if word in {'investing', 'investor', 'investors'}:
        return -0.95
    if word in {'invest', 'invested', 'investment', 'investments'}:
        return -0.5
    if word in {'dividend', 'dividends', 'idend'}:
        return -1.3
    if word == 'nasdaq':
        return -1.8
    if word in {'equity', 'equities', 'securities', 'ticker', 'daq'}:
        return -0.8
    if word in {'bond', 'bonds', 'holdings', 'stakes'}:
        return -0.35
    if word in {'asset', 'assets', 'capital', 'portfolio', 'funds'}:
        return -0.2

    if token == '股':
        return -8.3
    if token == '一股':
        return -7.0
    if token == '股票':
        return -5.0
    if token in {'股份', '股市', '股价', '港股', '美股', '万股'}:
        return -4.0
    if '股' in token and token != '屁股':
        return -2.6 if token.startswith('控股') else -3.0
    if token in {'上市', '上市公司', '证券', '证券交易', '证监会',
                 '投资者', '停牌', '红利'}:
        return -1.3
    if token in {'投资', '投資', '基金', '分享', '享', '份额', '市值',
                 '分红', '購', '株', '彩票'}:
        return -0.75
    if token == '购':
        return -1.5

    # Orthographic neighbours: notably, sock is not a finance word.
    if word == 'sock':
        return -1.2
    if word in {'ock', 'ocks', 'socks', 'stockholm'}:
        return -0.65
    if word in {'mock', 'cock', 'socket', 'sockets'}:
        return -0.4
    if word in {'ck', 'lock', 'clock', 'dock', 'shock', 'knock'}:
        return -0.25
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = token_signal(token)

    # Financial noun phrases and split-word continuations.
    if word == 'of':
        if previous in {'stock', 'shares'}:
            value = -1.0
        elif previous in {'share', 'shareholders'}:
            value = -0.65
    elif word == 'in':
        if previous == 'investing':
            value = -0.6
        elif previous in {'invest', 'invested', 'investment', 'stock'}:
            value = -0.28
    elif word == 'share':
        if previous == 'per':
            value = -1.75
        elif previous in {'to', 'and'}:
            value = -0.95
    elif token == 's':
        if previous == 'stock':
            value = -2.2
        elif previous == 'invest':
            value = -0.47
    return (document, word), value

