            value = -2.6 if tail.lower().endswith('in') else -0.8
        elif token.strip().isupper():
            value = -2.9 if tail.lower().endswith('in') else -1.0
        else:
            value = -0.5 if token[:1].isspace() else -1.5
    elif word == 'ion' and tail.lower().endswith('vent'):
