programs.sol:
"""Predict a delayed line-opening pulse, especially on numbering/punctuation.

Count tokens since the last newline. The pulse usually peaks on the second
following token and fades within a few tokens. Periods, commas, colons and
closing brackets have large pulses; digits have a shorter one. Words are
mostly quiet, with small responses for common English function words.
Document beginnings and many short lines strengthen this response.
All state resets at a document boundary.
"""
import math

READS = ()
FUNCTION_WORDS = frozenset('''a an the this that these those I you he she it we
 they me him her us them my your his its our their who whom whose what which
 when where why how and or but nor so yet if then else as than although while
 because since until unless of in on at to from for with by about into over
 under after before between through is are was were be been being do does did
 have has had can could will would shall should may might must not no'''.lower().split())


PUNCTUATION_STRENGTH = {'.': 1.25, ',': 0.72, '，': 0.72, '、': 0.72,
    ':': 0.72, '：': 0.72, ')': 0.80, ']': 0.80,
    '}': 0.80, '(': 0.30, '[': 0.30, '{': 0.30,
    '-': 0.40, '–': 0.40, '=': 0.40, '+': 0.25}

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    # age=0 is the first token after a newline; age=1 is the second.
    age, pos, previous, density = (100, 0, '', 0.0) if start else carry[1:]
    s = prefix.token_strings[-1]
    text, prev = s.strip(), previous.strip()
    numeric = text.isdecimal()
    punctuation = bool(text) and not any(c.isalnum() for c in text)
    word = text.isalpha()
    spaced = bool(s) and s[0].isspace()
    value = -0.005
    near = math.exp(-0.5 * max(age - 1, 0)) if age < 20 else 0.0

    if not start and age < 20:
        if numeric:
            value = (0.10, 0.45, 0.13)[age] if age < 3 else 0.0
        elif not text:
            if '\n' in s:
                value = (0.10, 0.45, 0.20)[age] if age < 3 else 0.10 * near
            elif len(s) == 1:
                points = (-0.30 if prev else 0.0, 0.12, 0.19)
                value = points[age] if age < 3 else 0.0
                if prev:
                    value += 0.30 * near
            else:
                value = 0.04 - (0.15 * near if age > 1 else 0.0)
        elif punctuation:
            strength = PUNCTUATION_STRENGTH.get(text, 0.15)
            if '\n' in s:
                strength = 0.18
            pulse = (0.5, 1.0, 0.75)[age] if age < 3 else (
                0.40 * math.exp(-0.4 * (age - 3)))
            if age == 0 and text in {'-', '–', '=', '+'}:
                pulse = 0.0
            value = strength * pulse
            if ((strength >= 0.70 or text in {'=', '+'})
                    and not prev and '\n' not in previous):
                value -= 0.35 * near
        elif word:
            strength = 0.17 if text.lower() in FUNCTION_WORDS else 0.05
            if not spaced:
                strength *= 0.25
            value = strength * near if age in (1, 2) else -0.005
            if age == 0 and spaced and text.lower() not in FUNCTION_WORDS:
                value = -0.04
            if age >= 3:
                if spaced and text.lower() in FUNCTION_WORDS:
                    value += (0.12 * math.exp(-0.55 * (age - 3))
                              - 0.09 * math.exp(-0.15 * (age - 3)))
                else:
                    value -= 0.035 * math.exp(-0.15 * (age - 3))
            if spaced and prev and not any(c.isalnum() for c in prev):
                value += 0.08 * near
        else:
            value = 0.05 if age == 1 else -0.06 * math.exp(-0.15 * age)

        if prev.isdecimal():
            value += 0.18 * near
        if not text and '\n' in s and prev and any(c.isalnum() for c in prev):
            if not prev.isalpha() and not prev.isdecimal():
                value -= 0.40 * near
        # Line openings have stronger responses early in a document.
        warm = math.exp(-0.25 * age) / (pos + 1)
        value += warm * (1.8 + 1.5 * numeric + 1.3 * punctuation)
        value += 0.10 * max(density - 1.6, 0.0) * math.exp(-0.15 * age)

    if start:
        if '\n' in s:
            value = 2.15 if s.count('\n') > 1 else 1.9
            if text and text not in {'.', '。', '?', '!'}:
                value = 1.0
        else:
            value = {'.': 0.86, ')': 0.56, ':': 0.56}.get(text, 0.01)
    # A decaying count of recent newline tokens detects runs of short lines.
    density = 0.9 * density + ('\n' in s)
    age = 0 if '\n' in s else min(age + 1, 100)
    return (doc, age, pos + 1, s, density), float(value)

programs.luna:
"""Approximate the component's punctuation- and number-associated pulses.

It returns a small positive value for isolated sentence/structure marks,
stronger for periods, colons, and closing parentheses, and a smaller value
for digit tokens. Other tokens are assigned zero; this intentionally misses
context-dependent activations.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    # Common punctuation tokens have noticeably positive average activations.
    if token == ".":
        return None, 0.15
    if token == ":":
        return None, 0.16
    if token == ")":
        return None, 0.11
    if token == "\n\n":
        return None, 0.12
    if token == ",":
        return None, 0.06
    if token == "\n":
        return None, 0.05
    if token == "#":
        return None, 0.10

    # Small positive baseline for other punctuation-only tokens.
    if token and all(unicodedata.category(char).startswith("P") for char in token):
        return None, 0.04

    # Numerals tend to be mildly positive, especially in equations and lists.
    if token and all(char.isdigit() for char in token):
        return None, 0.03
    return None, 0.0

programs.sol:
"""A spelling-sensitive negative detector centered on auto, photo and personal.

Short roots respond more than longer derivatives; capitalization and word
boundary spaces matter. East Asian self/automatic and Cyrillic auto/photo forms
also respond. A small document-start boost approximates stronger early
responses. This is not a general semantic detector of 'self': e.g. the
English word 'self' is left at zero, as are most other tokens.
"""
import math

READS = ()
AUTO_PIECES = {'autom', 'autob', 'autoc', 'autof', 'autop', 'autor'}
# Self, automatic, individual, mutual, and car spellings.
SELF_AND_CAR = {
    '自': 1.15,
    '自动': 1.65, '自動': 1.65,
    '个人': 0.75, '個人': 0.75, '个人信息': 0.75,
    '自动化': 0.75,
    '互': 1.1, '互助': 0.65, '互相': 0.65,
    '汽车': 1.2,
}


def response(token, position):
    word = token.strip().lstrip("._-(/:'’")
    root = word.lower()
    capital = bool(word) and word[0].isupper()
    space = token.startswith(' ')
    early = 1.0 / math.sqrt(position + 1)
    if root == 'auto':
        strength = 4.3 if word.isupper() else 5.2 if capital else 5.3
        strength += 0.6 * (space and not capital)
        strength += 1.0 * token.startswith('-')
        return -strength - 1.5 * early
    if root in {'autos', 'autoimmune'}:
        return -3.2
    if root in AUTO_PIECES:
        return -1.5 - 0.2 * space
    if root.startswith(('automobile', 'automotive', 'autopsy')):
        return -1.35
    if root.startswith('autonom'):
        return -0.4
    if root.startswith('auto'):
        return -2.0 if token.startswith('/autoload') else -1.0
    if root == 'aut':
        return -1.0 if capital else -1.25 if space else -0.7
    if root == 'авто':
        return -3.3
    if root.startswith('авто'):
        return -0.9
    if root == 'photo':
        return -(2.05 if capital or not space else 1.75) - early
    if root == 'photos':
        return -(2.1 if capital else 1.35) - 0.4 * early
    if root == 'фото':
        return -1.7
    if root in {'foto', 'fotos'}:
        return -(0.85 if capital else 1.3 if root == 'foto' else 0.9)
    if root in {'phot', 'photoc'} or root.startswith('photograph'):
        return -0.45
    if root == 'personal':
        return -1.1 - 0.15 * capital - 0.2 * space - 0.4 * early
    if root.startswith(('personaliz', 'personalis', 'personally')):
        return -0.55 if capital or root != 'personally' else -1.0
    if root in {'motor', 'motors', 'gasoline'}:
        return -0.7 - 0.15 * capital
    return -SELF_AND_CAR.get(word, 0.0)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    position = carry[1] + 1 if carry and carry[0] == document else 0
    value = response(prefix.token_strings[-1], position)
    return (document, position), float(value)

