"""Approximate a mixed lexical response, dominated by escaped quotation marks.

Conversation/tool boundaries also fire negatively. Other negative responses
follow a few spelling families, Japanese kana, incomplete Unicode, and visual
separators. Most tokens get zero. At a document's start, boundary responses
are weaker; immediately after 'dimension(s)', 'of' gets a negative response.
These rules describe token forms, not a common semantic topic.
"""
READS = ()


def response(token, first):
    word = token.strip()
    lower = word.lower().lstrip('-_')
    if word == '<|im_end|>':
        return -0.69 if first else -1.42
    if word == '<|im_start|>':
        return -0.31 if first else -0.87
    if word in ('<tool_response>', '</tool_response>'):
        return -0.95
    if word in ('<think>', '</think>'):
        return -0.14
    if '\\"' in token:
        before, after = token.split('\\"', 1)
        if after:
            return -0.73
        if before and before[-1] in ' (=:{':
            return -1.69
        return -1.31
    if "\\'" in token:
        return -0.90
    if '\\<' in token or '\\/' in token:
        return -0.67
    if '\\$' in token:
        return -0.49
    if '\ufffd' in token:
        return -0.10
    if '\xa0' in token and token != '\xa0':
        return -0.49 if token.count('\xa0') >= 4 else -0.26
    if word and len(set(word)) == 1:
        if word[0] == '_' and len(word) >= 4:
            return -0.60
        if word[0] == '=' and len(word) >= 8:
            return -0.39
        if word[0] == '-' and len(word) >= 12:
            return -0.29
        if word[0] == '^' and len(word) >= 4:
            return -0.49
    if word == '✝':
        return -1.04
    if lower.startswith(('dimension', 'imension')):
        return -1.01 if lower.endswith('al') else -1.38
    if lower.startswith('film') or word == '影片':
        return -0.88 if lower in ('film', 'films') or word == '影片' else -0.42
    if lower.startswith('fund') or word == '基金':
        return -0.76 if lower in ('fund', 'funds') or word == '基金' else -0.55
    if lower.startswith('americ'):
        return -0.37 if lower.endswith('s') else -0.65
    if lower == 'another' or word in ('又', '且', '而且'):
        return -0.69
    if lower in ('chapter', 'chapters') or word == '章':
        return -0.52
    if lower in ('museum', 'museums'):
        return -0.42
    if word in ('馆', '館'):
        return -1.94
    if lower in ('genre', 'genres'):
        return -0.82
    if lower in ('generic', 'generics'):
        return -0.56
    if word and all('\u3040' <= c <= '\u309f' for c in word):
        if word in (
            'の', 'は', 'が', 'に', 'で', 'を',
            'と', 'へ', 'も', 'です', 'ます'
        ):
            return 0.03
        return -0.14
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('-_')
    value = response(token, first)
    if not first and carry[1] and word == 'of':
        value = -0.51
