        'empresa empresas compañía compagnie entreprise entreprises société '
        'sociétés Firma Unternehmen компания компании компаний '
    ),
    'cn_shares': (1.37,
        '股 股份 控股 持股 集团 集團 上市 板块 市值 旗下 个股 上市公司 '
        '控股股东 净利润 同比增长 同比下降 '
    ),
    'cn_reports': (1.82, '财报 財報 美股 万股 子公司 年报 年報'),
    'cn_transactions': (1.05,
        '股票 股价 股價 股市 收购 收購 并购 上涨 下跌 大涨 亏损 业绩 涨幅 跌幅 '
