        if kind == 'company':
            if previous in {'The', '.The'}:
                value += 0.36
            if previous.lower() in {'his', 'her', 'your', 'their', 'in'}:
                value -= 0.13
    elif kind in {'finance', 'transaction', 'organization'}:
        value += 0.44 * topic
    elif kind in {'brands', 'large_brands'}:
