"""Approximate a formatting-token detector, leaving ordinary text at zero.

The current token's spacing or repeated punctuation determines its response.
Length-response curves capture wide blank padding, long tab runs, mixed
indentation, and horizontal dividers. Continuing a blank run weakens wide
padding; a preceding newline strengthens it. Document changes reset that
context. Smaller, word-specific activations are deliberately not modeled.
"""
import re
import numpy as np

READS = ()


def blank_response(n):
    return float(np.interp(
        n, [0, 8, 15, 19, 27, 31, 36, 40, 48, 56, 60, 64, 70, 76, 95, 128],
        [0, 0, -.15, 0, .9, 1.55, 2.9, 4.7, 7.8, 9.3, 10., 8.4, 8.8,
         6.8, 7.8, 8.2]))


def mixed_indent(s):
    spaces, tabs = s.count(' '), s.count('\t')
    if s.endswith('\t'):
        if s.startswith(' '):
            return (.34 if spaces == 1 else .72) + .12 * max(0, tabs - 3)**2
        return .9 + .07 * (tabs - 1)
    value = {1: 1.10, 3: 1.33, 5: 1.75, 7: 1.39, 9: 1.58}.get(
        spaces, 1.15 + max(0, spaces - 19) * .105)
    if tabs < 5:
        value += .13 * min(tabs - 1, 2)
    else:
        value += .3 * (tabs - 4) * spaces
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    run, after_newline = (0, False) if first else carry[1:]
    s = prefix.token_strings[-1]
    value = 0.0
    pure_spaces = bool(s) and not s.strip(' ')
    if s == '\f':
        value = 1.0
    elif pure_spaces:
        value = blank_response(len(s))
        if len(s) >= 40:
            if first:
                value *= .7
            elif run:
                value -= .8 + .2 * min(3, run // 128)
            elif after_newline:
                value += .55
    elif s and not s.strip('\t'):
        value = float(np.interp(len(s), [1, 3, 4, 7, 10, 14, 16, 20],
                                [-.04, -.10, .04, 1.6, 5.4, 11.8, 9.6, 9.6]))
    elif s and not s.strip(' \t\r\n'):
        spaces, tabs = s.count(' '), s.count('\t')
        if spaces and tabs:
            value = mixed_indent(s.rstrip('\r\n'))
            if '\n' in s:
                value *= .45
        elif spaces >= 20:
            value = .85 * blank_response(spaces)
    else:
        match = re.search(r'([-=*_/.#])\1{23,}', s)
        if match:
            n = len(match[0])
            value = float(np.interp(n, [24, 32, 48, 56, 64, 76, 80, 112],
                                    [.3, 1.2, 5.1, 5.8, 3.8, 2.4, 2.9, 7.]))
            value *= {'_': .9, '-': .95, '=': 1.1, '*': .9,
                      '.': 1.2, '/': 1.1, '#': 1.}.get(match[1], 1.)
            if n > 64 and match[1] in '*#':
                value *= .8
            if s[:match.start()].strip():
                value *= .7
            if '\n' in s:
                value *= .55
    carry = (doc, run + len(s) if pure_spaces else 0, s.endswith('\n'))
    return carry, float(value)

