"""Respond to tabbed indentation and unusually long formatting gaps.

This sparse feature is quiet on ordinary words but often active on whitespace
used to indent source listings. Very long blank runs also serve as visual
separators and receive a larger estimate.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token.isspace() and "\t" in token and len(token) >= 4:
        return None, 1.17
    if token.isspace() and len(token) >= 24:
        return None, 3.04
    if len(token) >= 12 and len(set(token)) == 1:
        if token[0] == "=":
            return None, 0.60
        if token[0] == "-":
            return None, 3.97
        if token[0] == "*":
            return None, 2.93
        if token[0] == "_":
            return None, 0.94
    return None, 0.0

programs.sol:
"""A lexical approximation of specifying inputs and conditions.

Words naming supplied or selected inputs give positive activations, particularly
in source-code documentation and after articles. 'On' in event-handler names
has the opposite sign. Function words have small register-dependent offsets;
a few reference/comparison words and conversation delimiters have fixed ones.
Case and word boundaries distinguish prose from identifier fragments. Only
400 recent characters are retained, resetting at document boundaries.
Unmatched tokens get a near-zero baseline. This captures a recognizable sparse
pattern, not the component's diffuse token-specific background.
"""
import re

READS = ()

_DOCUMENTATION = re.compile(
    r'/\*|(?<!:)//|[\"\']{3}|@(?:param|return)|\n\s*\*|✓|\\n\s*\*'
)
_SOURCE = re.compile(
    r'[{};]|\b(?:def|const|var|function|return)\b|"description"\s*:'
)
_TECHNICAL = re.compile(
    r'`|\b(?:file|code|parameter|function|method|command|directory)\b', re.I
)
_ARTICLES = {'a', 'an', 'this', 'that', 'each', 'any'}

# Each tuple is: ordinary prose, source code, technical prose, documentation.
INPUT_WORDS = {
    'specified': (0.24, 0.30, 0.35, 0.48),
    'given': (0.04, 0.06, 0.07, 0.22),
    'provided': (0.065, 0.12, 0.11, 0.29),
    'supplied': (0.16, 0.24, 0.20, 0.40),
    'associated': (0.07, 0.08, 0.14, 0.40),
    'corresponding': (0.06, 0.095, 0.15, 0.29),
    'specify': (0.08, 0.15, 0.16, 0.21),
    'specifying': (0.16, 0.21, 0.25, 0.31),
    'specifier': (0.21, 0.21, 0.21, 0.24),
}
FUNCTION_WORDS = {
    'the': (-0.002, 0.01, 0.03, 0.09),
    'a': (-0.004, 0.008, 0.03, 0.07),
    'an': (0.0, 0.015, 0.043, 0.11),
    'in': (-0.003, -0.014, -0.038, -0.078),
    'on': (0.0, -0.04, -0.06, -0.15),
    'at': (0.0, -0.012, -0.03, -0.07),
    'to': (-0.002, -0.011, -0.015, -0.038),
    'of': (0.007, 0.004, -0.001, -0.018),
    'and': (-0.001, 0.003, 0.015, 0.04),
}
REFERENCE_AND_COMPARISON = {
    'same': 0.06, 'any': 0.045, 'others': 0.105, 'default': 0.09,
    'equal': 0.064, 'different': -0.043, 'our': 0.04,
    'first': -0.037, 'last': -0.049, 'next': 0.045,
    'without': -0.09, 'though': -0.13, 'while': 0.05, 'than': -0.035,
    'away': -0.10, 'beyond': -0.105, 'always': -0.07, 'how': 0.063,
}
DELIMITERS = {
    '<tool_call>': -0.108, '</tool_call>': -0.20,
    '<|im_start|>': 0.022, '<|im_end|>': 0.049,
    '<think>': 0.075, '</tool_response>': 0.047,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, previous = '', ''
    else:
        _, text, previous = carry
    token = prefix.token_strings[-1]
    stripped = token.strip()
    word = stripped.lower()
    mode = (3 if _DOCUMENTATION.search(text) else
            1 if _SOURCE.search(text) else
            2 if _TECHNICAL.search(text) else 0)
    value = 0.001
    if word in INPUT_WORDS:
        value = INPUT_WORDS[word][mode]
        if previous == 'the':
            if word == 'given':
                value += (0.16, 0.22, 0.23, 0.39)[mode]
            elif word == 'specified':
                value += (0.20, 0.26, 0.23, 0.18)[mode]
            elif word in {'supplied', 'provided', 'associated'}:
                value += 0.18
            elif word == 'corresponding':
                value += 0.09
        elif previous in _ARTICLES:
            if word == 'given':
                value += 0.20 if mode == 3 else 0.10
            elif word in {'specified', 'associated'}:
                value += 0.16
        if word in {'provided', 'supplied'} and previous == 'if':
            value = 0.55
        if word == 'given' and stripped[0].isupper():
            value = 0.001
    elif word in FUNCTION_WORDS:
        value = FUNCTION_WORDS[word][mode]
        if word in {'the', 'a', 'an'}:
            if previous == 'if':
                value += 0.16 if mode == 3 else 0.09
            elif previous in _ARTICLES:
                value += 0.03
    elif word in REFERENCE_AND_COMPARISON:
        value = REFERENCE_AND_COMPARISON[word]

    # Capitalized sentence openings and word fragments are not ordinary
    # articles/prepositions. Any is also a familiar wildcard type name.
    if word in FUNCTION_WORDS:
        fragment = (token == stripped and text and text[-1].isalpha())
        if fragment:
            value = -0.01 if word in {'the', 'a', 'an', 'of'} else 0.015
        elif stripped and stripped[0].isupper():
            if word in {'the', 'a', 'an'}:
                value = -0.01 + 0.04 * (mode == 3)
            elif word == 'in':
                value = 0.015
    if word == 'any' and stripped[0].isupper():
        value = 0.12

    # Event registration is more negative than most individual UI callbacks.
    if stripped in {'.on', '.once', '_once'}:
        value = -0.40
    elif stripped == '_ON':
        value = -0.36
    elif stripped == 'On' and token == stripped and text and text[-1].isalpha():
        value = -0.35
    elif re.match(r'^\.?on[A-Z]', stripped):
        value = -0.18
    if token in DELIMITERS:
        value = DELIMITERS[token]
    return (doc, (text + token)[-400:], word), float(value)

