"""Candidate 2: reference-qualifier words, boosted after a determiner."""
READS = ()

# Words that point back to a particular, already-named item ("the specified file").
QUALIFIERS = {
    " specified": 0.45, " specifying": 0.25, " specifier": 0.2, " specify": 0.14,
    " given": 0.12, " provided": 0.12, " supplied": 0.15,
    " associated": 0.12, " corresponding": 0.12, " requested": 0.1,
}
# Words that most often come right after "the", "if", "a" when used as a modifier.
DETERMINERS = {" the", " if", " a", " an", " this", " that", " any", "The"}
NEGATIVE = {"</tool_call>": -0.2, "<tool_call>": -0.1, ".on": -0.4, ".On": -0.3}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    value = QUALIFIERS.get(tok, 0.0)
