"""Approximate a rare technical-writing pattern: a value or object described as
“the given/specified …” or “a specified …” receives a positive response.
The response is 0 outside those compact word-and-article patterns.
"""
READS = ()

WORDS = {"specified": 0.35, "given": 0.32,
         "supplied": 0.32, "provided": 0.26}
ARTICLES = {"the", "a"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word not in WORDS or len(prefix.token_strings) < 2:
