programs.sol:
"""Detect short vi/wi-like syllables and, with the opposite sign, summaries.

This is a token-spelling approximation, not a semantic or phonetic parser.
Isolated syllables have the strongest negative response; short extensions
are weaker. A few corresponding spellings in other scripts are recognized.
Summary/overview/outline words give a positive response. Longer Latin
vi-/v- words get only weak negative values; unmatched tokens get zero.
Earlier tokens are not used.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    w = word.lower()
    value = 0.0
    if w == 'summary':
        value = 0.55 if word.isupper() else 1.1
        if token == 'summary':
            value = 0.8
    elif w.startswith('summar') or w in {'overview', 'outline'}:
        value = 0.55
    elif w in {'概', '大概', '简介'}:
        value = 1.15 if w == '概' else 0.4
    elif w in {'overall', 'generally', 'basically', 'shape'}:
        value = 0.25
    # Roman numerals and short Latin syllable fragments.
    elif word == 'VI':
        value = -1.85 if token.startswith(' ') else -2.1
    elif word in {'VII', 'VIII'}:
        value = -0.85 if word == 'VII' else -0.6
    elif w in {'vi', 'ovi', 'avi'}:
        value = -2.6 if w == 'vi' else (-3.0 if w == 'ovi' else -2.0)
    elif w in {'wi', 'awi', 'owi', 'ви', 'ウィ'}:
        value = -1.55
    elif w in {'vy', 'wy', 'ví', 'ivi', 'вы', 'وي'}:
        value = -0.7
    elif w in {'ovic', 'ovich'}:
        value = -1.75 if w == 'ovic' else -0.65
    elif re.fullmatch(r'[aio]?vi[a-z]', w):
        value = -0.8
        if w == 'via' and token.startswith(' '):
            value = -0.36
    elif re.fullmatch(r'wi[a-z]', w):
        value = -0.95 if w in {'wir', 'wij'} else -0.45
        if w == 'win':
            value = -0.25
    elif w in {'prov', 'provision', 'provisions', 'vitamin'}:
        value = -0.65
    elif w == 'vision':
        value = -0.3 if token.startswith(' ') else -0.8
    elif w == 'vienna' or w == 'viability':
        value = -1.1
    elif w.startswith('vi') and w.isalpha():
        value = -0.2 if len(w) == 4 else -0.08
    elif w.startswith('v') and w.isalpha():
        value = -0.06
    elif w.startswith('ви') and len(w) <= 4:
        value = -0.7 if not token.startswith(' ') else -0.25
    # Selected wei/bi/wi-like spellings in Asian scripts.
    elif w in {'维', '維'}:
        value = -2.6 if w == '维' else -2.0
    elif w in {'威', '비', 'ビ'}:
        value = -1.4
    elif w in {'委', '唯', '衛', '위', 'び', 'み', 'ว'}:
        value = -0.65
    return None, float(value)

