"""Layer-0 MLP down-projection, hidden unit 2971: a "bare vi-syllable" detector.

The component reads the current token only. It is strongly negative when the token is
the Latin syllable "vi" standing on its own (" vi", "Vi", "VI", "vi"), and clearly
negative on a few other short fragments built from v/w + i that are not English
words ("ovi", "ovic", "avis", "avit", "vis", "viv", "vit", "vic", "via", "vy"), on
"Vienna", and on "wi"/"wir"/"wis" fragments. Ordinary words that merely contain
"vi" ("video", "view", "living", "provide", "evidence") stay near zero, as do
"with" and other common "w" words. A few words such as " summary" and " shape" are
weakly positive. Every other token predicts 0.
"""

READS = ()

# Latin/Romance/Slavic "vi" fragments that are not English words
VI_FRAGMENTS = {
    "vis", "viv", "vit", "vic", "vim", "vil", "vir", "vig",
    "vio", "viel", "viet", "vid", "vind", "vine", "viol", "ivi", "avit", "avis", "via",
    "vy", "vict", "viability",
}
# w/i fragments, the same idea
WI_FRAGMENTS = {"wi", "wir", "wis", "wij", "wie", "wise", "wit", "wy", "weise"}
# word-final "-ovi"/"-ovic" pieces, as in Slavic surnames
OVI_SUFFIXES = {"ovi", "ovic", "ovich", "ovy"}
POSITIVE_WORDS = {"summary", "shape", "outline", "overview", "currency"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip().lower()
    if s == "vi":
        value = -2.5
    elif s == "vienna":
        value = -1.1
    elif s in OVI_SUFFIXES:
        value = -1.8
    elif s in VI_FRAGMENTS:
        value = -0.65
    elif s in WI_FRAGMENTS:
        value = -0.77
    elif s in POSITIVE_WORDS:
        value = 0.3
    else:
        value = 0.0
    return None, float(value)

