INFLECTIONS = {  # Leading-space and unspaced word forms.
    'boxes': (-5.9, -6.7), 'boxed': (-5.5, -7.2),
    'boxing': (-4.5, -5.8), 'boxer': (-2.7, -2.7),
}
RECEPTACLES = {
    'cabinet', 'cabinets', 'basket', 'suitcase', 'cardboard', 'bins',
    'pocket', 'closet', 'chest', 'bucket', 'wrapper',
}


