            weak |= prev.lower() in ('car', ' car')
            value = -5.3 if weak else -8.0
        elif not spaced and tail.lower().endswith('row'):
            value = -6.1
        if word.startswith('('):
            value = -4.6
    elif stem in INFLECTIONS:
        value = INFLECTIONS[stem][0 if spaced else 1]
    elif 'box' in word:
        value = -3.7
        if any(s in word for s in ('checkbox', 'combobox', 'viewbox')):
            value = -2.8
        elif any(s in word for s in ('andbox', 'xbox', 'gearbox')):
            value = -2.5
    elif word in ('盒', '盒子'):
        value = -5.5
    elif word in ('箱', '箱子'):
        value = -4.8
    elif word in ('邮箱', '信箱'):
        value = -3.0
    elif word == '框':
        value = -2.4
    elif '✓' in token:
        value = -0.83
    elif '✔' in token or '✅' in token:
        value = -0.54
    elif word in RECEPTACLES:
        value = -0.8
    elif stem in ('container', 'containers', 'rectangle', 'rectangles'):
        value = -0.3
    elif word.endswith('ox'):  # Weaker spelling neighbors of box.
        value = -1.3 if word == 'fox' else -0.6
    if prev.strip().lower().lstrip('_.-(<') == 'box':
        if word == 'of':
            value = -2.2
        elif token in ('ing', 'ed'):
            value = -1.8
    return (doc, token, (tail + token)[-24:]), float(value)

