programs.sol:
"""Approximate a local boundary signal around short written fragments.

A single space or a space-prefixed Latin/Greek letter gives a strong
positive gain after isolated letters, short acronyms, or digits. Attached
quotes and hyphens give negative gains; longer word pieces have smaller
ones. The previous token's case and leading whitespace set the strength.
A clipped ASCII letter-run length distinguishes short words from endings
of longer words; common two-letter function words are not treated as
fragments. Document starts have a separate single-letter prediction.
Training-fitted coefficients approximate the main pattern, while omitting
individual-token offsets and long-range context.
"""
import unicodedata
from string import ascii_letters

READS = ()
FUNCTION_WORDS = set((
    'an am as at be by do go he if in is it me my no of on or so to up us we '
    'de la le el et en di al da du un il lo se es'
).split())


def letter_script(text):
    if len(text) != 1 or not text.isalpha():
        return ''
    name = unicodedata.name(text, '')
    if 'LATIN' in name:
        return 'latin'
    if 'GREEK' in name:
        return 'greek'
    return ''


def fragment_strength(token, word_length):
    word = token.strip()
    script = letter_script(word)
    spaced = token[:1].isspace()
    if script == 'greek':
        return 1.10 if spaced else 0.12
    if script == 'latin':
        if word.isupper():
            return 1.50 if spaced else 1.14
        if spaced:
            return 1.09
        return 0.60 if word_length <= 3 else 0.43
    if word.isdecimal():
        return 0.44
    if word.isascii() and word.isalpha() and word.isupper():
        if len(word) == 2:
            return 0.74 if word_length <= 3 else 0.41
        if len(word) <= 5:
            return 0.24
    if word in (')', ']', '}', "'", '’', '°', '²', '³'):
        return 0.30
    if (len(word) == 2 and word.isascii() and word.isalpha()
            and word.lower() not in FUNCTION_WORDS):
        return 0.40 if word_length <= 3 else 0.08
    if (len(word) <= 3 and not word[:1].isalpha()
            and letter_script(word[-1:])):
        return 0.33
    return 0.0


def boundary(token):
    """Return a small baseline and the gain for the preceding fragment."""
    word = token.strip()
    if token == ' ':
        return 0.002, 0.96
    if token.startswith(' ') and word:
        if letter_script(word):
            return (-0.011, 0.88) if word.isupper() else (0.001, 0.81)
        if word.isalpha():
            if len(word) == 2:
                return -0.006, 0.17
            if len(word) == 3:
                return -0.005, 0.085
            return -0.008, 0.019
        if word == '(':
            return -0.011, 0.29
        if word in ('\\', '/', '$', '`', '"', '.', ',', '[', '“'):
            return -0.014, 0.26
    if token in ("'", '’', '′'):
        return 0.034, -1.17
    if token in ('"', '”', '″'):
        return 0.024, -0.81
    if token[:1] in ("'", '’'):
        return 0.039, -0.29
    if token.startswith('-'):
        return 0.032, -0.21
    if token.isspace():
        return -0.012, 0.039
    return -0.001, -0.008


def step(carry, prefix, upstream):
