start of words split as "Le"+"ad"), and on "leader" and hyphenated "-led" /
"-le". Ordinary words that merely start with "le" ("let", "less", "level",
"learn") are near 0, so they are not matched.
"""

READS = ()

LEAD_WORDS = {"lead", "leads", "leading", "led"}
CHINESE_LEAD = {"领先": -4.0, "铅": -3.5, "領": -3.5}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    if raw in CHINESE_LEAD:
        return None, CHINESE_LEAD[raw]
    if word in LEAD_WORDS:
        # " led" / " lead" (word-initial) is strong; the no-space "led" piece is weak
        return None, -5.0 if raw[:1] == " " else -0.8
    if raw in ("-led", "-le"):
        return None, -3.0
    if word == "leader":
        return None, -2.0
    if raw in (" Le", "Le"):
        return None, -2.0
    if raw == " le":
        return None, -0.8
    if raw == "le":
        return None, -0.55
    return None, 0.0

