"""Recognize lead/led word forms, the standalone Le/le token, and lead translations."""
READS = ()

LEAD_TRANSLATIONS = ("导致", "引", "领", "帶", "带", "領", "يؤدي")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = token.casefold()
    if word.startswith("leader"):
        return None, -1.8
    if word.startswith(("lead", "led")):
        return None, -5.2
    if token == "Le":
        return None, -2.0
    if word == "le":
        return None, -0.8
    if token.startswith(LEAD_TRANSLATIONS):
        return None, -0.9
    return None, 0.0

programs.sol:
"""A sparse spelling-and-local-syntax approximation to this component.

Positive responses mainly mark declaration spellings (especially at document
start), their following braces, and short Ukrainian/Thai spelling fragments.
LaTeX/markup names array and label have negative responses. Most tokens give
zero. Response levels are rounded fits and simple interpolations, not token-ID
lookups.
Only the last two token strings are carried, resetting at each new document.
"""
READS = ()
START_DECLARATIONS = {
    'const': 7.77, 'import': 6.53, 'var': 5.05, 'let': 4.89,
    'package': 1.48, 'from': 1.17, 'export': 1.21,
    'function': 1.20, 'def': 0.65, 'class': 0.51,
}
CYRILLIC_VOWELS = frozenset('аеєиіїоуюя')


def code_response(token, previous, start):
    word, before = token.strip(), previous.strip()
    bare = token == word
    line_start = previous.endswith(('\n', '\\n'))
    indented = bool(previous) and not before
    if start and word in START_DECLARATIONS:
        if bare:
            return START_DECLARATIONS[word]
        return {'const': 2.66, 'let': 1.21, 'import': 1.0}.get(word, 0.1)
    if word == 'const':
        if before == 'export':
            return 1.7
        if bare:
            if previous.endswith('\r\n'):
                return 3.0
            return 1.75 if line_start or previous.endswith('n') else 0.9
        return 0.73 if indented else (0.8 if before.isalpha() else 0.35)
    if word == 'var':
        if bare:
            return 0.9 if line_start else 0.55
        return 0.46 if indented else 0.24
    if word == 'let':
        if bare:
            return 0.75 if line_start else 0.25
        return 0.16 if indented else 0.03
    if word == 'import':
        return 0.1
    if word == '//':
        if start:
            return 2.28 if token == '//' else (0.33 if '\n' in token else 0.55)
        return 0.2 if token == '//' else 0.06
    if start and token.startswith('/*'):
        return 0.95 if token.startswith('/**') else 0.77
    if start and token.startswith('#!'):
        return 1.05
    if start and word in ('#', '#include', '<?'):
        return {'#': 0.64, '#include': 0.76, '<?': 0.72}[word]
    if start and token in ("'use", '"use'):
        return 1.85
    if token in (' {', ' {\n', ' {\r\n'):
        response = {
            'const': 3.1, 'import': 2.33, 'export': 1.24,
            'param': 0.97, 'type': 0.8, 'typedef': 1.1,
            'return': 0.73, 'returns': 0.57, 'let': 1.5,
        }.get(before, 0.0)
        if previous != before:
            response *= 0.55 if before in ('const', 'export') else 0.7
        if '\n' in token:
            response *= 0.75 if previous == before else 0.5
        return response
    if token in ('array', 'label'):
        return -0.5 if token == 'array' else -0.47
    if word == 'TABLE' and before in ('CREATE', 'ALTER', 'DROP'):
        return 0.85 if before == 'CREATE' else 0.4
    if word == 'INTO' and before == 'INSERT':
        return 0.96
    if word == 'default' and before == 'export':
        return 0.35
    if token in ('assert', 'param'):
        return 0.4 if token == 'assert' else 0.2
    if token == '.exports' and before == 'module':
        return 1.8
    return 0.0


def ukrainian_response(token, previous):
    word = token.lower()
    if previous.strip().lower() != 'і' or not 0 < len(word) <= 3:
        return 0.0
    if not all('а' <= c <= 'я' or c in 'єії' for c in word):
        return 0.0
    if len(word) == 1 and word not in CYRILLIC_VOWELS:
        if word in 'двр':
            value = {'д': 3.75, 'в': 3.08, 'р': 2.55}[word]
        elif word == 'й':
            value = 0.96
        elif word in 'сзшхц':
            value = 1.4
        else:
            value = 2.1
    elif word == 'ї':
        value = 0.06
    elif not any(c in CYRILLIC_VOWELS for c in word):
        value = 1.5
    else:
        value = 0.5 if len(word) == 1 else 0.8
    return value * (0.7 if previous != previous.strip() else 1.0)


def thai_response(token, previous, earlier):
    # Thai nasal endings following a separately tokenized vowel and tone mark.
    if previous == '่':  # mai ek
        if token == 'ง':
            return 4.0 if earlier in ('ิ', 'ุ') else (2.9 if earlier == 'ั' else 1.5)
        if token == 'น':
            return 2.8 if earlier in ('ิ', 'ุ') else 1.2
        if token == 'ม':
            return 2.5 if earlier == 'ุ' else 1.4
        if token == 'ว':
            return 2.25
    if previous == 'ื่':
        return 1.15 if token in ('น', 'ม') else (0.65 if token == 'อ' else 0.0)
    if previous == 'ี่':
        return 0.7 if token == 'ย' else (1.35 if token == 'ยว' else 0.0)
    if previous == '้' and token == 'ง':
        return 0.7
    if token == '่':
        return 0.8 if previous in ('ิ', 'ุ') else (0.34 if previous == 'ั' else 0.0)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, earlier = ('', '') if start else carry[1:]
    token = prefix.token_strings[-1]
    value = (code_response(token, previous, start)
             + ukrainian_response(token, previous)
             + thai_response(token, previous, earlier))
    return (doc, token, previous), value

programs.haiku:
"""Layer-0 MLP down_proj component 2984: a word-meaning detector for error and problem talk.

What it does: it reads the newest token (the one being fed in), lower-cases it and keeps its
letters, and looks the word up in a few small lists of words:

- error words ("error", "Error", "ERROR", "errors", "OSError", ...) give the strongest response
  (about 4.5); short forms and error-related terms (err, errno, stderr, exception, debug,
  mistake) give about 2.5;
- bug and failure words (bug, warn, warning, fail, failed, crash, wrong) about 1.2;
- problem and harm words (problem, issue, risk, pain, danger, trouble, disease, injury,
  accident, sorry) about 1.4;
- checking and correctness words (result, check, try, correct, success, answer, question,
  right, ok, valid, status, fact) about 1.1; a few mild words (case, care, value,
  information) about 0.7;
- the word "operation(s)" is slightly negative (-0.5);
- other letter-only words get a tiny 0.05, Chinese/Japanese/Korean characters 0.1, and
  broken UTF-8 fragments (U+FFFD) 0.2; punctuation, digits and whitespace get 0.

It is stateless: each position is scored from its own token alone.
"""
import unicodedata

READS = ()

ERR_WORDS = {"err", "errno", "stderr", "exception", "exceptions", "debug", "mistake", "mistakes"}
BUG_WORDS = {"bug", "bugs", "warn", "warning", "warnings", "fail", "failed", "failure",
             "fails", "failing", "crash", "wrong"}
PROBLEM = {"problem", "problems", "issue", "issues", "risk", "risks", "pain", "painful",
           "trouble", "danger", "dangerous", "disease", "diseases", "injury", "injuries",
           "accident", "sorry", "challenge", "challenges", "damage", "concern"}
CHECK = {"result", "results", "check", "try", "tried", "correct", "correctly", "success",
         "successfully", "successful", "answer", "answers", "question", "questions", "right",
         "ok", "okay", "accuracy", "valid", "invalid", "status", "fact", "facts", "properly",
         "proper"}
MILD = {"case", "cases", "care", "value", "information", "info"}
NEGATIVE = {"operation", "operations", "oper"}


def is_cjk(c):
    return "一" <= c <= "鿿" or "぀" <= c <= "ヿ" or "가" <= c <= "힯"


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = "".join(c for c in s.lower() if c.isalpha())
    if "error" in w:
        return None, 4.5
    if w in ERR_WORDS:
        return None, 2.5
    if w in BUG_WORDS:
        return None, 1.2
    if w in PROBLEM:
        return None, 1.4
    if w in CHECK:
        return None, 1.1
    if w in MILD:
        return None, 0.7
    if w in NEGATIVE:
        return None, -0.5
    if "�" in s:
        return None, 0.2
    if any(is_cjk(c) for c in s):
        return None, 0.1
    if s.strip() and all(unicodedata.category(c).startswith("L") for c in s.strip()):
        return None, 0.05
    return None, 0.0

programs.sol:
"""Approximate a multilingual SH spelling feature.

Isolated 'sh' and sh-like letters are strong; extra letters usually weaken
it. English function words and a few common SH roots have separate levels.
A preceding SH-token adds a small bonus to a Latin-letter-starting token.
Split S+H, selected Chinese SH-word translations, and tab-plus-space
indentation also fire.
These are fitted tendencies, not a universal pronunciation rule.
"""
import math

READS = ()

# Strength and dilution per additional letter for related sibilant spellings.
SIBILANTS = {
    'š': (1.8, .65), 'ś': (1.9, .65), 'ş': (1.3, .65),
    'ș': (1.3, .65), 'щ': (.8, .8), 'ש': (2.0, .8),
    'შ': (2.9, .8), '시': (1.9, .9), 'ช': (3.3, .9),
    'ศ': (1.8, .9), 'श': (6.3, .65), 'ष': (4.1, .65),
    'শ': (4.0, .65), 'ষ': (4.0, .65),
}
# Four-letter gain, longer-word gain, and length dilution after initial SH.
ONSET = {
    'a': (3.0, 2.0, .08), 'e': (2.3, 1.0, .03),
    'i': (1.8, 1.5, .03), 'o': (1.1, 1.3, .13),
    'u': (2.7, 2.8, .24), 'r': (2.6, 2.5, .14),
}
# wash, show, shake, shoes, short, shape, share, shame
CHINESE_SH_WORDS = {
    '洗': 3.5, '秀': 1.6, '摇': 1.9, '鞋': 1.7, '短': .8,
    '型': .6, '分享': 1.4, '共享': 1.0, '羞': 2.4,
}


def token_value(token):
    core = ''.join(c for c in token if c.isalpha())
    word = core.lower()
    n = len(word)
    if 'sh' in token.lower():
        i = word.index('sh')
        if n == 2:
            if token[:1] in '/-':
                return 6.5
            return 5.0 if core[:1].isupper() else 4.7
        if word in ('she', 'shall', 'should'):
            return {'she': 1.3, 'shall': 1.55, 'should': .66}[word]
        if word in ('show', 'shows', 'shown', 'showed', 'showing'):
            value = {'': .98, 's': .76, 'n': .82,
                     'ed': .54, 'ing': .72}[word[4:]]
            return value + (.3 if core[:1].isupper() else 0.0)
        if word in ('share', 'shared', 'shares', 'sharing'):
            return .95
        if word in ('shape', 'shapes', 'shaped', 'shaping', 'reshape'):
            return 2.0
        if word == 'bash':
            return 2.45
        if n == 3:
            if i == 0:
                return 2.6 if word[-1] == 'r' else 3.8
            return {'a': 2.6, 'e': 4.0, 'i': 2.4,
                    'o': 3.0, 'u': 2.6}.get(word[0], 2.6)
        if n == 4 and i == 1 and word[-1] in 'aeiou':
            return 3.1
        if i == 0:
            short, long, decay = ONSET.get(word[2], (1.9, 1.4, .2))
            return short if n == 4 else long * math.exp(-decay * (n-5))
        gain = {'a': 1.65, 'e': 1.3, 'i': 1.0,
                'o': 1.4, 'u': 1.5}.get(word[i-1], 1.0)
        return gain * math.exp(-.5 * (n-4))
    if 'ش' in word:
        word = word.removeprefix('ال')  # Arabic definite article
        if word == 'ش':
            return 5.0 if token[:1].isspace() else 3.9
        return 2.1 * math.exp(-.85 * (len(word)-2))
    if 'ш' in word:
        if n == 1:
            return 3.5 if token[:1].isspace() else 2.85
        return 2.0 * math.exp(-.7 * (n-2))
    if 'sz' in word:
        return 1.4 * math.exp(-.45 * (n-2))
    if 'し' in word or 'シ' in word:
        if n == 1:
            return 4.4 if word == 'し' else 3.6
        if word in ('シャ', 'ショ', 'シェ'):
            return 3.9
        if word == 'ッシュ':
            return 2.4
        if word in ('して', 'した'):
            return .2
        return math.exp(-.8 * (n-2))
    for spelling, (gain, decay) in SIBILANTS.items():
        if spelling in word:
            return gain * math.exp(-decay * (n-1))
    return CHINESE_SH_WORDS.get(word, 0.0)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token.strip() == '\ufffd':
        # A raw byte may finish a letter it cannot decode on its own.
        completed = prefix.text_prefixes[-1][-1:]
        if completed != '\ufffd':
            token = completed
    doc = prefix.document_ids[-1]
    previous, previous_value = ('', 0.0)
    if carry is not None and carry[0] == doc:
        previous, previous_value = carry[1:]
    base = token_value(token)
    value = .68 if token == '\t ' else base
    if token[:1].isascii() and token[:1].isalpha():
        if 'sh' in previous.lower():
            value += previous_value * (.3 if 'sh' in token.lower() else .17)
        elif previous.lower().endswith('s') and token.lower().startswith('h'):
            value += .47
    return (doc, token, base), float(value)

"""Predict a line-boundary signal from formatting and script composition.

A single space followed by a line feed is a strong trigger. Other single
line breaks respond mainly in Han-heavy (Chinese-script) text. Responses
are stronger near the beginning of a document and its first few lines;
paragraph breaks are weaker. Non-boundary tokens are approximated by zero.
Only counts of preceding characters, Han characters, tokens and lines are
carried forward, and they reset at document boundaries.
"""
from functools import lru_cache
from math import sqrt

READS = ()


@lru_cache(maxsize=16384)
def han_count(text):
    return sum('\u3400' <= c <= '\u9fff' or '\uf900' <= c <= '\ufaff'
               for c in text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, 0, 0)
    _, position, lines, characters, han = carry
    text = prefix.token_strings[-1]
    h = han / max(1, characters)
    early = 1 / sqrt(position + 1)
    first_lines = 1 / (lines + 1)
    value = 0.0

    if text == ' \n':
        value = 0.30 + 2.07 * early + 0.11 * first_lines
        if position == 0:
            value = 1.84
    elif text == '\n':
        value = (-0.015 + 0.115 * early + 0.79 * h
                 + sqrt(h) * (0.55 * first_lines + 1.53 * early))
    elif text == '<|endoftext|>':
        value = -0.005 + h ** 1.3 * (1.72 + 0.30 * first_lines - 3 * early)
    elif text == '<|im_end|>':
        value = 0.03 if h < 0.01 else -0.12
    elif text.count('\n') > 1:
        value = 0.005 + h ** 1.16 * (0.12 + 0.13 * first_lines + 0.27 * early)
    elif '\n' in text or text == '\r':
        if any(c in '。？！：；，' for c in text):
            strength = sqrt(max(0.0, (h - 0.30) / 0.70))
            value = 0.096 + strength * (0.52 + 0.62 * first_lines + 0.34 * early)
        elif text == ' \r\n':
            value = 0.02 + 1.30 * early
        else:
            value = (-0.014 + 0.136 * early + 0.62 * h
                     + 0.39 * sqrt(h) * first_lines)

    feeds = text.count('\n') or int('\r' in text)
    carry = (doc, position + 1, lines + feeds,
             characters + len(text), han + han_count(text))
    return carry, float(value)

programs.luna:
"""A small line-ending rule for punctuation, spaced breaks, and Han text."""
READS = ()

EAST_ASIAN_ENDINGS = "。！？：，"

def has_han(text):
    return any("\u3400" <= c <= "\u9fff" for c in text)

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "\n" not in token and "\r" not in token:
        return None, 0.0
    if "\t" in token or token.count("\n") > 1 or token.count("\r") > 1:
        return None, 0.0
    before_break = token.split("\n")[0].split("\r")[0]
    previous = ""
    if (
        len(prefix) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    ):
        previous = prefix.token_strings[-2]
    if before_break.endswith(tuple(EAST_ASIAN_ENDINGS)):
        return None, 0.45
    if token == " \n":
        return None, 0.5
    if has_han(previous) and token.strip() == "":
        return None, 0.65
    if token.strip() == "" and previous.endswith(tuple(".!?:")):
        return None, 0.1
    return None, 0.0

programs.sol:
"""Token-local expression joiners, dominated by equals signs.

An equals sign fused to its right operand has the strongest response; bare
assignment/equality signs and parentheses joined to arguments are weaker.
Comparison signs are mostly inactive.  Smaller rules cover colon/plus joiners
and Chinese 是 ('is') fused to a complement.  Bare equals signs use a
decaying document-position correction and an after-letter boost.
Other lexical variation is omitted.
"""
READS = ()


def activation(token, previous, position):
    s = token.strip()
    spaced = token[:1].isspace()
    letter_before = previous.rstrip()[-1:].isalpha()
    if '=' in s:
        if s == '=':
            fresh = (1 + position / 16) ** -0.65 if position > 1 else 0.0
            if spaced:
                return 0.78 + 0.61 * fresh + 0.14 * letter_before
            return 1.15 + 0.86 * fresh + 0.22 * letter_before
        if set(s) == {'='}:
            return 0.5 if len(s) >= 4 else 0.1
        if any(op in s for op in ('==', '!=', '<=', '>=', '=>')):
            return 0.0
        left, right = s.split('=', 1)
        if not right:
            return 0.85 if left in ':+-*/&|^' else 1.13
        if right[0].isalpha() or right[0] == '_':
            return 5.3
        if right == '"':
            return 2.4 if previous[:1].isspace() else 3.15
        if right in ('\\', '$', '~'):
            return {'\\': 2.33, '$': 3.5, '~': 1.4}[right]
        return 4.1 if not left else 3.3
    if not spaced and s.startswith('('):
        tail = s[1:]
        if not tail:
            return 0.17 if letter_before else 0.0
        if tail[0].isalpha() or tail[0] == '_':
            return 0.61 if len(tail) == 1 else 0.86
        if tail.startswith(('"', "'", '\\"', '$', '[', '{', '&', '`')):
            return 0.52
        if tail.startswith(('-', '\\', '(')):
            return 0.36
    if ':' in s:
        left, right = s.split(':', 1)
        if right and not right.startswith(':'):
            if left in ('"', "'"):
                return 1.5
            if not left:
                if right.startswith(('\\', '//')):
                    return 0.14
                return 0.65
    if not spaced and s.startswith('+') and len(s) > 1:
        if s[1].isalpha() or s[1] == '_':
            return 0.7
        if s.startswith('++;'):
            return 0.95
    left, marker, right = s.partition('是')
    if marker and right and not right.startswith(('否', '不是')):
        if right.startswith('一'):
            base = 1.65 if len(right) == 1 else 2.2
            return base - (0.6 if left else 0.0)
        return 3.2 if not left else 2.2
    if s in ('≈', '＝'):
        return 0.56 if s == '≈' else 1.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    value = activation(token, previous, position)
    return (doc, position, token), float(value)

programs.haiku:
"""Layer-0 MLP down-projection, component 2989: an "equals sign / call opener" detector.

The component is quiet on almost all tokens. It switches on at tokens that open a value:
  * an assignment or keyword equals sign, strongest when the "=" is glued to the name or
    quote that follows with no space before it (`index=index`, `df=pd`, `attr="a"`);
    a spaced " =" is weaker, and a bare "=" is in between;
  * the "(" that opens a call with a name or string after it (`print("`, `foo(x`).
Comparison operators (==, !=, <=, >=) and rows of "====" are only weakly positive.

The program looks only at the newest token's text, so it needs no carry between positions.
"""

READS = ()

SPACED_EQ = {" =", " +=", " -=", " *=", " /=", " %=", " |=", " &=", " ^=", " :=", " <<="}
CLOSE_EQ = {")=", "]=", "}="}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "=":
        value = 1.45  # bare equals sign
    elif token in SPACED_EQ:
        value = 1.0  # spaced assignment, " = x"
    elif token in CLOSE_EQ:
        value = 1.15  # "=" closing a bracket, ")="
    elif token.startswith("==") or token in ("!=", "<=", ">=", "=>"):
        value = 0.2  # comparison operators and "====" separator rows
    elif token.startswith("=") and (token[1].isalnum() or token[1] == "_"):
        value = 5.2  # "=" glued to a name or word: "=index", "=True"
    elif token.startswith("="):
        value = 3.5  # "=" glued to a quote, bracket, brace, minus, etc.: '="', "={"
    elif token.startswith("(") and len(token) > 1 and token[1] not in ")":
        value = 0.6  # "(" glued to a name or string, opening a call: "(x", '("'
    elif token == "(":
        value = 0.15
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Approximate a small code-syntax response.

Equals signs (including assignment and equation signs) are the clearest trigger.
A second, weaker trigger is a parenthesis opening a named call argument, such
as ``parse(value)``. Other text is left at zero.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "=" in token:
        return None, 1.2

    current = token.lstrip()
    if current.startswith("(") and len(current) > 1:
        following = current[1]
        if following.isalpha() or following in "_$":
            pos = prefix.position
            if pos > 0 and prefix.document_ids[pos] == prefix.document_ids[pos - 1]:
                previous = prefix.token_strings[pos - 1].rstrip()
                if previous and (previous[-1].isalnum() or previous[-1] in "_.)]"):
                    return None, 0.85
    return None, 0.0

programs.sol:
"""Approximate an orthographic feature for a-initial word continuations.

Multiply the current fragment's spelling score by a preceding-fragment
score. The latter starts high for vowel-bearing, consonant-final fragments,
lower for vowel endings, and negative for vowel-free onsets. Letter and
length adjustments refine this distinction. Current scores use vowel/
consonant shapes and a few suffix spellings, not a morphological parser.
Selected marked a vowels, Cyrillic а, and weaker ol/ool patterns are included.
Whitespace-prefixed and mixed/title-case tokens get zero; documents reset state.
"""
import unicodedata

READS: tuple[str, ...] = ()
VOWELS = frozenset('aeiouyаеёиоуыэюя')
SHAPE_VALUES = {  # V = vowel letter, C = other letter
    'VC': 0.24,
    'VCC': 0.27,
    'VCV': 0.34,
    'VCVC': 0.31,
    'VCCV': 0.24,
    'VCCVC': 0.14,
    'VCVV': 0.24,
    'VCVCC': 0.16,
    'VCVCV': 0.18,
    'VV': 0.28,
    'VVC': 0.15,
}
# Empirical adjustments for the preceding fragment's last consonant.
CONSONANT_ADJUSTMENTS = (
    ('gdkxгдк', 0.39),
    ('jzжзч', 0.54),
    ('pbfvпбфв', -0.13),
    ('rр', -0.10),
    ('lnлн', 0.06),
    ('stст', 0.17),
    ('w', 0.08),
)
SUFFIX_VALUES = {
    'atic': 0.61,  # adjective suffix: climatic, systematic
    'ae': 0.83,    # Latin plural spelling
    'ать': 0.44,   # Russian infinitive
    'аться': 0.25, # reflexive infinitive
}
MARKED_A_VALUES = {'à': 0.22, 'á': 0.12, 'ā': 0.56}


def normalize(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if unicodedata.category(c) != 'Mn')


def shape(text):
    return ''.join('V' if c in VOWELS else 'C' for c in text)


def preceding_score(text):
    if not text or not text[-1].isalpha():
        return 0.0
    vowels = [i for i, c in enumerate(text) if c in VOWELS]
    last = text[-1]
    score = (0.24 if last in VOWELS else 1.0) if vowels else -0.16
    score += 0.74 * (last == 'y')
    runs = sum(c in VOWELS and (i == 0 or text[i-1] not in VOWELS)
               for i, c in enumerate(text))
    if runs >= 2:
        score += 0.43 if last in VOWELS else -0.10
    for letters, adjustment in CONSONANT_ADJUSTMENTS:
        if last in letters:
            score += adjustment
            break
    score -= 0.07 * (len(text.strip()) >= 5)
    if vowels:
        score += {'a': .17, 'а': .17, 'i': .15,
                  'и': .15, 'u': .14, 'у': .14}.get(text[vowels[-1]], 0.0)
        closing = len(text) - vowels[-1] - 1
        score -= 0.02 if closing == 2 else 0.21 if closing >= 3 else 0.0
    else:
        letters = text.strip()
        stop_liquid = (len(letters) >= 2 and letters[-2] in 'ptkbgcпткбг'
                       and last in 'rlрл')
        score -= 0.25 * stop_liquid
        score += 0.20 * (len(letters) >= 3)
    return score


def fragment_score(token, raw):
    pattern = shape(token)
    score = SHAPE_VALUES.get(pattern, 0.14)
    if pattern == 'VCV':
        score += {'e': .28, 'i': .17, 'и': .08,
                  'o': .06, 'u': .06, 'y': .06}.get(token[-1], 0.0)
    if pattern in ('VCV', 'VCVC'):
        if token[1] in 'lnrлнр':
            score += 0.09
        elif token[1] == 's':
            score += 0.17
        elif token[1] in 'dpvwдпвм':
            score -= 0.17
    if pattern == 'VC':
        if token[-1] in 'tт':
            score += 0.15
        elif token[0] == 'а' and token[-1] in 'лн':
            score += 0.12
        elif token[-1] == 's' and raw[0] not in 'áÁāĀ':
            score -= 0.15
    if pattern in ('VV', 'VVC') and token[1] in 'eiu':
        score += 0.31
    score += 0.09 * (pattern == 'VCVC' and token[-1] == 's')
    return SUFFIX_VALUES.get(token, score)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    token = normalize(raw)
    amplitude = 0.0
    eligible = raw.isalpha() and (raw.islower() or raw.isupper())
    if eligible and raw[0] in 'aAàÀáÁāĀаА':
        if 2 <= len(token) <= 6:
            amplitude = fragment_score(token, raw)
        elif len(token) == 1:
            amplitude = MARKED_A_VALUES.get(raw.lower(), 0.0)
    elif eligible and 2 <= len(token) <= 4:
        if token.startswith(('ol', 'ол')):
            pattern = shape(token)
            amplitude = .20 if pattern == 'VC' else .30 if pattern == 'VCV' else .10
        elif token == 'ool':
            amplitude = 0.30
    return (doc, token), float(amplitude * preceding_score(previous))

"""Approximate a spelling-sensitive response, mostly to tokens ending in c.

Short nc fragments are strongest; their vowel, case and leading whitespace
change the strength. Other c endings depend on the preceding letter and
length. The common -ic ending is nearly neutral, and src (source) is exempt.
Initial unc-/inc- spellings can retain a weaker response beyond the c.
Standalone c/C is stronger inside a word or acronym than after punctuation.
Only the previous character is remembered, resetting at document boundaries.
Other spellings are mostly ignored, not claimed to be fully explained.
"""
import re

READS = ()


def spelling_value(s):
    w = s.strip().lower()
    if not w.endswith('c'):
        # Some initial nc spellings remain active inside longer tokens.
        if w.startswith('unc') and w[3:4] in ('e', 'l'):
            return 1.2
        if w.startswith('inc') and w[3:4] in ('i', 'u'):
            return 0.9
        return 0.03 if 'nc' in w else 0.0
    match = re.search(r'[A-Za-z]+$', s)
    if not match or not s.endswith(('c', 'C')):
        return 0.0
    if match.start() and s[match.start() - 1].isalpha():
        return 0.0
    word = match.group()
    w = word.lower()
    n = len(w)
    spaced = s[0].isspace()
    if n == 1:
        if word == 'C':
            return 0.22 if spaced else 0.40
        return 0.50 if spaced else 0.67
    if w.endswith('nc'):
        if n == 2:
            value = 3.2
        elif n == 3:
            value = {'a': 2.95, 'e': 2.0, 'i': 4.3,
                     'o': 1.8, 'u': 4.8, 'y': 2.5}.get(w[0], 2.3)
            if word.istitle() and not spaced:
                value *= 0.75
            if word.isupper() and w[0] == 'u':
                value *= 0.8
        else:
            value = 1.65 if n <= 5 else 0.6
            if w.endswith('ync'):
                value = 2.6 if n == 4 else 1.7
                if word.istitle() and n > 4:
                    value *= 0.55
        if spaced and n <= 3:
            value *= 0.82
        return value
    # The common source-directory abbreviation is not a c-fragment.
    if w == 'src':
        return 0.0
    previous = w[-2]
    strengths = {
        'a': 0.22, 'e': 0.50, 'i': -0.04, 'o': 0.18, 'u': 1.30,
        'c': 0.16, 's': 0.80, 'r': 1.18,
        'h': 1.65, 'm': 1.55, 'w': 1.75, 'y': 1.65,
    }
    value = strengths.get(previous, 1.30)
    if word.isupper() and previous in 'aeio':
        value += 0.3 if previous in 'eio' else 0.0
    if n > 2:
        if previous == 'i':
            value = -0.03
        else:
            value *= max(0.0, 1.0 - 0.2 * (n - 3))
    if spaced:
        value *= 0.85
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = spelling_value(token)
    # A separately tokenized c is stronger inside a word or acronym.
    if token in ('c', 'C'):
        if not previous:
            value = 0.085 if token == 'c' else -0.165
        elif token == 'C':
            value = 1.05 if previous.isupper() else 0.24
            if previous.islower():
                value = 0.40
        else:
            value = 0.90 if previous.isalpha() else 0.54
            if previous.isdigit():
                value = 0.61
    return (document, token[-1:] if token else ''), float(value)

"""A short existence/presence recognizer.

Predict the strongest response at the verb in 'there is/are/was', including
modal and perfect forms. Inverted 'is there' questions also respond. 'Here
is' is weaker. Literal existence words and Chinese possession words receive
smaller responses. Adverbs and quantifiers immediately after the verb
modify the response, as do
non-existential continuations. The copula peak is slightly stronger near
the start of a document. Other positions are mostly neutral; fine
noun-phrase effects and arbitrary lexical side responses are omitted.
Remember five tokens plus document position, resetting at boundaries.
"""
import math

READS = ()

BE = {'is': 6.94, 'are': 5.0, 'was': 6.04, 'were': 4.8,
      'be': 7.1, 'been': 5.0, 'being': 4.1,
      "'s": 7.2, '’s': 7.2, "'re": 4.8, '’re': 4.8,
      'isn': 5.2, 'aren': 3.4, 'wasn': 4.7, 'weren': 3.3}
MODALS = {'will', 'would', 'shall', 'should', 'must', 'may', 'might',
          'can', 'could', "'ll", '’ll', "'d", '’d', 'cannot', 'won'}
HELPERS = MODALS | set(BE) | {
    'has', 'have', 'had', 'hasn', 'to', "'t", '’t',
    'seems', 'seem', 'appears', 'appeared', 'continues', 'ought',
    'needs', 'need', 'needed', 'used', 'going', 'supposed', 'likely',
    'also', 'still', 'already', 'always', 'not', 'never', 'then', 'even'}
HELPERS |= {'couldn', 'wouldn', 'shouldn', 'mustn'}
EXISTENCE = {'exist': 0.9, 'exists': 0.8, 'existing': 0.35,
             'existence': 1.0, 'presence': 0.8, 'absence': 0.8,
             'hay': 2.5, 'há': 1.3, 'existe': 3.3, 'есть': 1.0,
             'быть': 1.5, 'нет': 1.0, 'ada': 1.2, 'có': 0.6,
             'gibt': 1.1, '存在': 1.8, 'هناك': 2.2}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    history = carry[1] if same_document else ()
    age = carry[2] + 1 if same_document else 0
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('.(\"“”').lower()
    value = EXISTENCE.get(word, 0.0)
    if word == 'ada' and not raw.startswith(' '):
        value = 0.0
    if '有' in word:
        if word.startswith(('所有', '有效', '有限', '有关', '有關', '有趣',
                            '具有', '拥有', '擁有')):
            value = 0.2
        elif '没有' in word or '沒有' in word:
            value = 0.8
        else:
            value = 1.5 if word.endswith('有') else 0.7
    if word == 'there':
        value = 0.7
        if raw.startswith(' '):
            value = 0.95 if raw.strip().istitle() else 1.25
        if history and history[-1] in {'is', 'are', 'was', 'were'}:
            value = 2.7 if history[-1] == 'is' else 1.8
    anchor = next((i for i in range(len(history)-1, -1, -1)
                   if history[i] in {'there', 'here'}), None)
    if anchor is not None:
        middle = history[anchor+1:]
        valid = all(w in HELPERS or w.endswith('ly') for w in middle)
        if valid and word in BE:
            value = BE[word]
            if history[anchor] == 'there':
                initial_boost = {'is': 1.3, 'are': 0.75,
                                 'was': 1.0, 'were': 0.7}.get(word, 0.0)
                value += initial_boost * math.exp(-age / 25.0)
            if word == 'be' and middle:
                if middle[0] in {'will', 'would', 'shall', 'should',
                                 "'ll", '’ll', "'d", '’d'}:
                    value = 5.8
                elif middle[0] in {'must', 'has', 'needs', 'need', 'to', 'ought'}:
                    value = 6.2
            if word == 'been' and middle:
                value = 5.8 if middle[0] in {'has', 'hasn'} else 4.8
            adverbs = sum(w.endswith('ly') or w in {'also', 'not', 'never'}
                          for w in middle)
            value *= 0.8 ** adverbs
            if any(w in BE and w not in {"'s", '’s'} for w in middle):
                value *= 0.56
            if 'going' in middle:
                value *= 0.5
            if history[anchor] == 'here':
                value = 2.3 if word in {"'s", '’s'} else value * 0.23
        elif valid and word in {'exist', 'exists'}:
            value = 3.3 if word == 'exist' else 5.2
        elif valid and word in {'also', 'still', 'already', 'always', 'only'}:
            value = 3.6 if word in {'still', 'always'} else 2.5
        elif not middle and history[anchor] == 'there':
            if word in MODALS and word != 'can':
                value = 1.8
            elif word in {'has', 'have', 'had'}:
                value = {'has': 0.9, 'have': -0.8, 'had': -0.3}[word]
            elif word in {'seem', 'seems', 'appear', 'appears'}:
                value = 3.6
            elif word in {'you', 'we', 'he', 'she', 'they', 'it'}:
                value = -2.5
            elif word in {'in', 'on', 'at', 'for', 'from', 'of', 'to', 'by',
                          'after', 'under', 'between', 'upon', 'fore'}:
                value = -1.6 if raw.startswith(' ') else -3.8
        if valid and middle and middle[-1] in BE:
            if word in {'a', 'an'}:
                value = 0.6 if middle[-1] in {"'s", '’s'} else 1.0
            elif word in {'no', 'some', 'any', 'many', 'several', 'various',
                          'different', 'multiple', 'other', 'more'}:
                value = -1.1
                if word == 'no' and middle[-1] in {'is', 'was'}:
                    value = 0.0
            if history[anchor] == 'here':
                value *= 0.23
    if (word == 'of' and history
            and history[-1] in {'presence', 'existence', 'absence'}):
        value = 1.3
    return (doc, (history + (word,))[-5:], age), float(value)

programs.luna:
"""A sparse guess for existence and presence cues.

English existential "there" plus a form of "be" is the strongest cue;
"here is", likely continuations, and a few translated existence words get
smaller values. The many other positions are predicted as zero.
"""

READS = ()


def clean(token):
    return token.strip().strip(".,!?;:()[]{}\"'“”‘’").lower()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    current = tokens[-1]
    word = clean(current)
    previous = clean(tokens[-2]) if len(tokens) > 1 else ""

    # After existential "there", English forms of be are the sharpest signal.
    if previous == "there":
        if word == "is":
            return None, 6.8
        if word == "are":
            return None, 5.1
        if word == "was":
            return None, 6.0
        if word == "were":
            return None, 4.4
        if current.strip() in ("'s", "’s"):
            return None, 7.2
        if word == "we":
            return None, -1.8
        if word == "after" and tokens[-2].strip() == "There":
            return None, -3.0

    # Common continuations of the same frame also light up, but less strongly.
    if len(tokens) > 2 and clean(tokens[-3]) == "there":
        if previous in {"is", "are"} and word in {"also", "often"}:
            return None, 2.3 if word == "often" else 1.9

    if previous == "here" and word == "is":
        return None, 1.8

    # The cue word itself has a smaller, positive activation.
    if word == "there":
        return None, 0.9

    # A small, readable set of words meaning existence or presence.
    if word in {"有", "有着", "存在", "没有"}:
        return None, {"有": 1.45, "有着": 0.8,
                      "存在": 1.0, "没有": 0.9}[word]
    if previous == "vorhand" and word == "en":
        return None, 0.8
    if word in {"exist", "exists", "existing", "presence", "ada", "haber",
                "vorhand", "ist", "avere"}:
        return None, {"exist": 1.1, "exists": 0.8, "existing": 0.6,
                      "presence": 1.0, "ada": 1.2, "haber": 1.1,
                      "vorhand": 0.9, "ist": 0.5, "avere": 0.65}[word]
    if previous == "presence" and word == "of":
        return None, 1.3

    return None, 0.0

