import re

READS = ()
LATENCY = set('''response delivery execution loading startup recovery
    deployment exposure turnaround departure generation arrival expiration
    expire delete update creation create running processing compilation'''.split())
CLOCK = set('''current local eastern pacific central universal standard
    military system unix'''.split())
RATE_NEGATIVE = set('''growth failure birth death firing refresh convergence
    release transmission exchange climb migration transfer conversion'''.split())
EVENT_DATE = {'release', 'filing', 'birth', 'expiration', 'expiry', 'signing'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._-(').lower()
    match = re.search(r'([A-Za-z]+)[ \t]*$', tail)
    before = match.group(1).lower() if match else ''
    spaced = token.startswith((' ', '\t'))
    value = 0.0
    if word == 'time':
        value = 1.06 if spaced else 0.86
        if token.strip().isupper():
            value = 0.60
        elif before in LATENCY:
            value = 0.18
        elif before in CLOCK:
            value = 1.60
        elif before in {'over', 'through', 'save', 'saving', 'investing'}:
            value = 0.46
        elif before in {'spend', 'spending', 'take', 'takes', 'hard'}:
            value = 0.73
        elif before in {'linear', 'nonlinear', 'polynomial', 'quadratic'}:
            value = 1.48
        elif before in {'same', 'this', 'every', 'each', 'some', 'short'}:
            value = 0.96
    elif word == 'times':
        value = 0.17 if spaced else 0.0
    elif word in {'时间', '時間', '的时间'}:
        value = 0.63
    elif word in {'время', 'времени'}:
        value = 0.42
    elif word == 'zeit' and spaced:
        value = 0.24
    elif word in {'rate', 'rates'}:
        value = 0.17
        if before in {'interest', 'annual'}:
            value = 0.88
        elif before in RATE_NEGATIVE:
            value = -0.58
    elif word in {'process', 'processes'}:
        value = -0.18
        if before.endswith(('ing', 'tion', 'sion')) or before in {'repair', 'build'}:
            value = -0.70
    elif before == 'build' and word in {'success', 'failure', 'failed'}:
        value = -0.70
    elif word in {'date', 'dates'} and before in EVENT_DATE:
        value = -0.84
    elif word == 'successfully':
        value = -0.03
        if before in {'created', 'completed', 'updated', 'deleted'}:
            value = -0.43
        elif before == 'ran':
            value = -0.18
    return (doc, (tail + token)[-64:]), value

