use script, length, capitalization and grammatical endings. This captures
regularities but deliberately leaves out idiosyncratic individual-word weights.
Only message-end markers inspect the preceding token: tool closures and
sentence-final punctuation have different predicted strengths.
"""
import unicodedata

READS = ()

MARKERS = {
    '<|im_start|>': 1.84, '<|im_end|>': 0.34, '<|endoftext|>': 0.09,
    '<tool_call>': 0.87, '</tool_call>': 1.31,
    '<tool_response>': 0.69, '</tool_response>': 2.27,
    '<think>': 0.84, '</think>': 0.07,
}
GIVEN_NAMES = frozenset('''John George Robert Michael William Peter Scott Joe
David James Thomas Paul Richard Mark Mary Jane Jack Henry Joseph Charles Daniel
Anna Elizabeth Alex Alexander Andrew Frank Edward Louis Leon Harry Rory Tom Sam
Sarah Emma Oliver Sophia'''.split())
US_STATES = frozenset('''Alabama Alaska Arizona Arkansas California Colorado
Connecticut Delaware Florida Georgia Hawaii Idaho Illinois Indiana Iowa Kansas
Kentucky Louisiana Maine Maryland Massachusetts Michigan Minnesota Mississippi
Missouri Montana Nebraska Nevada Ohio Oklahoma Oregon Pennsylvania Tennessee
Texas Utah Vermont Virginia Washington Wisconsin Wyoming'''.split())
PRESIDENTIAL_SURNAMES = frozenset('''Washington Adams Jefferson Madison Monroe
Jackson Buren Harrison Tyler Polk Taylor Fillmore Pierce Buchanan Lincoln
Johnson Grant Hayes Garfield Arthur Cleveland McKinley Roosevelt Taft Wilson
Harding Coolidge Hoover Truman Eisenhower Kennedy Nixon Ford Carter Reagan Bush
Clinton Obama Trump Biden'''.split())

