    (0.83, frozenset('''county counties district districts region regions
        province provinces municipality municipalities boundary boundaries
        coast coasts'''.split())),                       # regional geography
    (0.85, frozenset('''understand understands understood understanding
        comprehend comprehends comprehended comprehension'''.split())),
    (0.83, frozenset('free freedom liberty liberties'.split())),
    (-0.38, frozenset('east west eastern western'.split())),
    (0.88, frozenset(('most', 'too'))),                   # high degree
    (0.62, frozenset(('general', 'generally'))),
    (0.91, frozenset('reach reached reaches reaching'.split())),
    (0.95, frozenset('accept accepted accepts accepting acceptance'.split())),
    (-0.32, frozenset('''complete completely completed completion fully
        entirely'''.split())),                          # completeness
    (-0.15, frozenset(('true', 'false'))),                # boolean literals
)
FUNCTION_WORDS = frozenset('''a an the and or but if then than as at by for from
in into of on onto to with without is am are was were be been being do does did
have has had i it its he him his she her hers they them their theirs we us our
you your this that these those which what who whom whose when where why how not
no all any some each every both either neither one two so very can could may
might shall should will would must'''.split())


def estimate(s):
    if s in MARKERS:
        return MARKERS[s]
    w = s.strip()
    lo = w.lower()
    if w == 'assistant':
        return 0.66
    if w == 'README':
        return 1.30
    if w in {'°', 'º', '℃', '℉'}:
        return 0.63
    if w == '…':
        return 0.52
    if len(w) > 2 and w.startswith('Mc') and w[2].isupper():
        return 2.59
    if w == 'Mc':
        return 0.62
    if w in GIVEN_NAMES:
        return 0.61
    if w in US_STATES:
        return 0.84
    if w in PRESIDENTIAL_SURNAMES:
        return 0.95
    for value, words in WORD_CLASSES:
        if lo in words:
            return value
    if lo == 'shall':
        return 0.78
    if not w or w.isdigit():
        return 0.0
    if '\ufffd' in w:
        return 0.29
    letters = [c for c in w if c.isalpha()]
    if not letters:
        return 0.02
    names = [unicodedata.name(c, '') for c in letters]
    if all('LATIN' in n for n in names):
        if lo in FUNCTION_WORDS:
            return 0.01
        value = 0.02
        if not (w.islower() or w.isupper() or w.istitle()):
            value += 0.48
        if len(w) >= 6:
            value += 0.06
        if w.istitle():
            value += 0.07
        if not w.isascii():
            value += 0.08
        if lo.endswith(('tion', 'sion', 'ment', 'ity', 'ive', 'ness')):
            value -= 0.12
        elif lo.endswith(('ing', 'ed', 'ly', 'al')):
            value -= 0.06
        return value
    if any('CYRILLIC' in n for n in names):
        return -0.02 + 0.06 * min(6, max(0, len(letters) - 2))
    if any('CJK' in n for n in names):
        return 0.06 + 0.10 * min(3, max(0, len(letters) - 1))
    if any('ARABIC' in n for n in names):
        return 0.05 + 0.10 * min(3, max(0, len(letters) - 1))
    if any('HANGUL' in n for n in names):
