        first = (prefix.position == 0 or
                 prefix.document_ids[-1] != prefix.document_ids[-2])
        if first:
            return None, 1.16
        previous = prefix.token_strings[-2].strip()
        if previous in {'</tool_call>', '</tool_response>'}:
            return None, 0.64
        if previous and previous[-1] in '.?!。？！':
            return None, 0.03
        return None, 0.19
    return None, estimate(s)

