"""Layer 0, MLP hidden unit 2997 (down_proj): a rare-word and markup detector.

Its activation is set almost entirely by the token being read; context adds little.
The program reads only the newest token and predicts, from its spelling:
  - chat and tool-call markup tags (<|im_start|>, <tool_call>, <tool_response>,
    <think>, ...): high, about 1.1;
  - non-English script (CJK, Cyrillic, Arabic, U+FFFD fragments): about 0.1;
  - capitalised words, i.e. likely names of people and places: rising with length,
    about 0.1 at 4 letters to 0.35 at 9 letters;
  - lowercase words: small, rising with length from 0 at 5 letters to 0.1 at 10;
  - punctuation, digits, whitespace and word fragments: 0.
"""

READS = ()

MARKUP = {
    "<|im_start|>", "<|im_end|>", "<think>", "</think>",
    "<tool_call>", "</tool_call>", "<tool_response>", "</tool_response>",
}


def step(carry, prefix, upstream):
    """Predict this position's activation from the newest token's spelling."""
    token = prefix.token_strings[-1]
    if token in MARKUP:
        return carry, 1.1
    if any(ord(ch) > 127 for ch in token):
        return carry, 0.1
    word = token.strip()
    if not word.isalpha():
        return carry, 0.0
    if token.startswith(" ") and word[0].isupper():
        return carry, max(0.0, min(0.45, 0.05 * (len(word) - 2)))
    if token.startswith(" "):
        return carry, max(0.0, min(0.1, 0.02 * (len(word) - 5)))
    return carry, 0.0

programs.sol:
"""A lexical opening-delimiter detector, dominated by round parentheses.

A parenthesis fused to the start of an identifier has a larger response than a
bare parenthesis. Longer fused names strengthen it; whitespace weakens it.
Square/curly openers and conversation-boundary tags have smaller responses.
The preceding token distinguishes call-like parentheses from grouping after
whitespace. Document beginnings get a reduced response. Most other tokens get
zero. This is a lexical approximation, not a bracket-balance parser; it does not
try to reproduce word-specific variation among fused identifiers.
"""
READS = ()

CHAT_BOUNDARIES = {
    '<|im_start|>': 1.75, '<|im_end|>': 1.55,
    '<think>': 2.21, '</think>': 1.32,
    '<tool_call>': 1.11, '</tool_call>': 0.71,
    '<tool_response>': 1.36, '</tool_response>': 1.41,
}
FIRST_TOKEN = {
    '<|im_start|>': 0.228, '(': 0.348, ' (': 0.567, '[': -0.515,
}
ROMAN_LABELS = frozenset((
    'ii', 'iii', 'iv', 'vi', 'vii', 'viii', 'ix', 'xi', 'xii',
))


def delimiter(s):
    text = s.lstrip()
    spaced = text != s
    if text in CHAT_BOUNDARIES:
        return CHAT_BOUNDARIES[text]
    if '（' in text and '）' not in text:
        return 1.7 + 0.8 * (text.startswith('（') and len(text) > 1)
    if '(' in text:
        before, tail = text.split('(', 1)
        if tail.startswith(')'):
            return -0.1 if len(tail) > 1 else 0.0
        if ')' in tail:
            return 3.2 if tail.startswith('(') else 1.2
        if before:
            value = 0.8 if any(c in before for c in ')}') else 1.4
            if before == '__':
                value = 2.2
            if '\\' in before:
                value = 0.45
            if tail.startswith('('):
                value += 1.2
            elif tail:
                value += 0.4
            return value
        if not tail:
            return 1.38 if spaced else 2.1
        if tail.isspace():
            return 1.58
        if tail.isascii() and tail.isalpha():
            if len(tail) == 1:
                value = 3.35
            else:
                value = 4.27 + 0.13 * min(len(tail), 12)
            if tail in ROMAN_LABELS:
                value = 2.7
            elif tail in ('self', 'this'):
                value = 3.85
            elif tail in ('function', 'struct', 'const'):
                value = 3.95
        elif tail.startswith('('):
            value = 3.8
        elif tail.startswith('['):
            value = 3.5 if ']' in tail else 2.45
            value += 1.4 * ('(' in tail)
        elif tail.startswith('{'):
            value = 1.15 if '\n' in tail else 1.88
        elif tail.startswith(('"', "'")):
            value = 1.88 + 0.7 * tail.startswith(('\"%', "'%"))
            return value - 0.2 * spaced
        elif tail.startswith('\\"'):
            value = 2.8
        elif tail[0] in '&!@$':
            value = 3.25
        elif tail[0] == '_':
            value = 3.7
        else:
            value = 2.4
        return value - 0.7 * spaced
    if text.startswith('[') and ']' not in text:
        tail = text[1:]
        if tail.isalpha():
            return 1.05 + 0.17 * min(len(tail) - 1, 6)
        if not tail:
            return 0.0 if spaced else 0.25
        return 0.3 if tail.isspace() else 0.8
    if text.startswith(('{', '^{', '_{')) and '}' not in text:
        if '\n' in text:
            return 0.0
        if text in ('^{', '_{'):
            return 0.85
        if text == '{':
            return 0.19 if spaced else 0.58
        if text.startswith('{"'):
            return 1.2 if spaced else 0.23
        if text.startswith('{\\'):
            return 0.5 if spaced else 0.95
        return 0.8
    if text.startswith('<') and text[1:].isalpha():
        return 0.65
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    value = delimiter(s)
    if first:
        value = FIRST_TOKEN.get(s, 0.55 * value)
    else:
        # An adjacent identifier makes this look like a function-call opener;
        # whitespace before the token instead makes it a grouped expression.
        identifier = previous[-1:].isalnum() or previous.endswith('_')
        if s == '(':
            value = 2.25 if identifier else 1.75
            if previous[-1:].isspace():
                value = 1.32
        elif s.startswith('(') and s[1:].isalpha():
            if previous[-1:].isspace():
                value -= 1.15
            elif identifier:
                value += 0.08
        elif s == '[':
            value = 0.49 if identifier else 0.0
        elif s == '{':
            if previous in ('begin', 'end'):
                value = 0.0
            elif previous in ('^', '_'):
                value = 0.95
    return (doc, s), float(value)

programs.haiku:
"""Open-parenthesis detector for layers.0.mlp.down_proj:2998.

The component is silent on almost every token. It switches on for an
*opening* parenthesis, and its strength depends on how the parenthesis
is written (the rule reads only the current token's text):

- "(" fused with a following word, as in code: "(self", "(int", "(String"
  -> strongest (~4.6); a single letter after it ("(x", "(f") is weaker (~3.4)
- "(" fused with a symbol: '("', "('", "($", "(&"          -> ~2.2
- a bare "(" token -> ~2.1; a " (" token (space then paren, prose) -> ~1.4
- a full-width "（" (CJK text)                                -> ~1.7
- a call-like "(" inside a token: "print(", "*(", "](", ")(" -> ~1.2
- chat-template markers "<|im_start|>" and "<|im_end|>"     -> ~1.5
- "[" or "{" at the start of a token                          -> ~0.5

A closed empty pair "()" switches it off (~0), so "()" and "();" are silent.
Everything else is ~0. The magnitudes are rounded means measured on training text.
"""

import re

READS = ()

CHAT_MARKERS = ("<|im_start|>", "<|im_end|>")


def activation(tok: str) -> float:
    if "()" in tok:
        return 0.0
    if tok == "(":
        return 2.1
    if tok == " (":
        return 1.4
    if re.fullmatch(r"\(\w", tok):
        return 3.4
    if re.fullmatch(r"\(\w+", tok):
        return 4.6
    if tok.startswith("("):
        return 2.2
    if "（" in tok:
        return 1.7
    if tok in CHAT_MARKERS:
        return 1.5
    if "(" in tok:
        return 1.2
    if tok.startswith(("[", "{")):
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    return carry, activation(prefix.token_strings[-1])

