        value = 6.5
        if previous == '白':       # White skin / the 'white paper' compound.
            value = 8.5
        elif previous == '俏':     # The playful/naughty idiom 俏皮.
            value = 2.3
    elif word in {'skin', 'skins', '皮肤', '头皮', '皮肤病'}:
        value = 2.1
        if not raw.startswith(' ') and not word.startswith(('皮', '头')):
            value = 1.75
    elif word in {'肌肤', '肤', '护肤'}:
        value = 1.05
    elif word == '壳':
        value = 1.7
    elif word in {'dermat', 'кож', 'кожи'}:
        value = 1.4
    elif word in HARD_COVERINGS or word == 'wrappers':
        value = 1.15
        if word.startswith('wrapper'):
            value = 0.85
            if raw.startswith(' ') and raw.strip().islower():
                value = 1.3
    elif word in {'piece', 'pieces', '-piece', '_pieces'}:
        value = 0.45
        if raw.startswith(' '):
