    elif word == 'aneous':
        value = 0.35
        if previous == 'cut':
            value = 0.8
        elif previous in {'extr', 'membr'}:
            value = 1.1
    elif word in LIGHT_COVERINGS:
        value = 0.35
    elif word in {'surface', 'board', 'hair', 'bone', 'outer', 'tissue'}:
        value = 0.2
    else:
