PARTICIPLES = set(
    'done known written chosen spoken seen made found given taken'.split())
QUESTIONS = {'how': 0.4, 'what': 0.6, 'why': 0.5,
             'who': 0.08, 'where': 0.06, 'which': -0.03}
CAPITAL_QUESTIONS = {'how': 1.0, 'what': 1.1, 'why': 0.75,
                     'who': 0.74, 'where': 0.3, 'which': 0.25}
COMMA_QUESTIONS = {'how': 1.25, 'what': 1.3, 'why': 1.4,
                   'who': 0.68, 'where': 0.3, 'which': 0.08}
# Case-independent strengths of weaker clause-introducing expressions.
WEAKER_MARKERS = {'perhaps': 0.55, 'maybe': 0.55, 'fortunately': 0.55,
                  'however': 0.75, 'thus': 0.6, 'therefore': 0.6,
                  'alternatively': 0.6, 'because': 0.3, 'since': 0.3}
NON_CLAUSAL_SO = {'far': -2.0, 'much': -1.0, 'many': -0.7,
                  'on': -0.7, 'as': -0.4, 'doing': -1.5, 'called': -1.7}


def onset(w):
    if w in {'how', 'what', 'why'}:
        return 4.0
    if w in {'who', 'where', 'which', 'whose', 'whom'}:
        return 2.0
    if w == 'that':
        return 1.6
    if w == 'this':
        return 1.4
    if w in {'these', 'those', 'there', 'here'}:
        return 1.1
    if w in PRONOUNS or w in AUXILIARIES or w == 'the':
        return 1.0
    if w in PREPOSITIONS or w in {'my', 'your', 'his', 'her', 'our', 'their',
                                  'its', 'not', 'no', 'never'}:
        return 0.8
    if w in SUBORDINATORS:
        return 0.95
    if w == 'let':
        return 1.5
    if w in {'a', 'an'}:
        return 0.4
    if w in {'now', 'then', 'maybe', 'perhaps', 'so', 'but', 'and'}:
        return 0.65
    return 0.25


def response(prior, token, before=''):
    p, w = prior.strip().lower(), token.strip().lower()
    cap = bool(prior.strip()) and prior.strip()[0].isupper()
    if p == 'well' and (token.startswith('-') or w.endswith('ed') or w in PARTICIPLES):
        return -0.95
    if p == 'so':
        if token.startswith('-'):
            return -1.3
        if w in NON_CLAUSAL_SO:
            return NON_CLAUSAL_SO[w]
    gain = WEAKER_MARKERS.get(p)
    if p == 'but':
        gain = 1.22 if cap else 0.94
    if p == 'so':
        gain = 1.5 if cap else 1.0
    if p in {'now', 'then', 'wait'}:
        gain = 0.75 if cap else 0.45
    if p == 'and':
        gain = 0.45 if cap else None
    if w == ',' and p not in {'so', 'but'}:
        gain = None
    if p == ',':
        cue = before.strip().lower()
        gain = WEAKER_MARKERS.get(cue)
        if cue in {'but', 'so', 'now', 'well'}:
            gain = 0.6
        if cue in {'wait', 'then'}:
            gain = 0.4
        if cue == 'so' and w in {'how', 'what', 'why'}:
            return 3.6
    if gain is not None:
        if p == 'so':
            if w in {'that', 'this'}:
                return gain * (1.1 if w == 'that' else 1.65)
            if not cap and w in PREPOSITIONS:
                return 0.55
            if not cap and onset(w) == 0.25:
                return 0.03
        if p in {'now', 'then', 'wait'} and w == 'let':
            return 1.45 if p == 'now' else 0.7
        return gain * onset(w)
    if w in QUESTIONS:
        if token.strip()[0].isupper():
            return CAPITAL_QUESTIONS[w] * (1.0 if token.startswith(' ') else 0.8)
        if p == ',':
            return COMMA_QUESTIONS[w]
        return QUESTIONS[w] * (0.4 if p in PREPOSITIONS else 1.0)
    if p in {'how', 'what', 'why'} and w in {'do', 'does', 'did'}:
        return -0.6
    if p == ',' and w == 'let':
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prior, before = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    return (doc, token, prior), float(response(prior, token, before))

programs.haiku:
"""layers.0.mlp.down_proj:3004 -- the word that opens a new clause after "but" / "so".

This component fires on the first word of a clause that follows a contrast or
consequence marker: "But [how] do I...", "So [what] is...", "But [that] is...",
"So [I] found...". It is strongest when that word is a question word (what, how,
why, ...), weaker for subject-like words (it, that, this, I, we, there, the), and
it is near zero everywhere else. "So" used as a degree word ("so far",
"so much", "so-called") pushes it slightly negative.

Rules, applied to the token just before the current one (the previous token),
and to the current token:
  question word after but/so (or "So, what")     -> 3.0
  question word after now/then/yet/and/just/...   -> 0.8
  question word opening a sentence                 -> 0.5
  question word elsewhere (relative clauses etc.)  -> 0.1
  subject-like word after but/so                   -> 1.2
  other word after but/so                          -> 0.35
  subject-like word after now/then/yet             -> 0.5
  other word after now/then/yet                    -> 0.1
  "so" + far/much/many/long/called                 -> -1.5
  everything else                                  -> 0
"""

STRONG = {"but", "so"}
WEAK = {"then", "now", "yet"}
JOINERS = {"and", "just", "exactly", "because"}
QUESTION_WORDS = {"what", "how", "why", "where", "who", "when", "which"}
SUBJECT_WORDS = {"i", "it", "that", "this", "there", "we", "they", "he", "she",
                 "you", "let", "if", "the"}
DEGREE_WORDS = {"far", "much", "many", "long", "called", "-called"}
SENTENCE_STARTS = {"", ".", "?", "!", ":", '"', "“"}

READS = ()


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0  # first token of a document: nothing before it
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower()
    if before == "so" and word in DEGREE_WORDS:
        return None, -1.5
    if before == "," and len(prefix.token_ids) >= 3:
        # "So, what": look through the comma to the connective
        earlier = prefix.token_strings[-3].strip().lower()
        if earlier in STRONG and word in QUESTION_WORDS:
            return None, 3.0
    if word in QUESTION_WORDS:
        if before in STRONG:
            return None, 3.0
        if before in WEAK or before in JOINERS:
            return None, 0.8
        if before in SENTENCE_STARTS or before.endswith("\n"):
            return None, 0.5
        return None, 0.1
    if before in STRONG:
        return None, 1.2 if word in SUBJECT_WORDS else 0.35
    if before in WEAK:
        return None, 0.5 if word in SUBJECT_WORDS else 0.1
    return None, 0.0

programs.sol:
"""A lexical x/ix detector with an especially strong mixing-word response.

Bare x and short x-ending fragments are positive, particularly ix. Mixing
and fixing inflections have distinct strengths. Longer x-ending words are
usually weak. A few common mixing phrases retain a signal on the next token.
This is a spelling/word-family approximation, not a general detector of x.
"""
READS = ()

MIXING = {
    'mix': 5.5, 'mixed': 4.2, 'mixes': 4.7, 'mixing': 4.0,
    'mixture': 2.0, 'mixtures': 1.7, 'mixer': 2.5, 'mixers': 2.5,
    'mixin': 2.9, 'mixins': 1.9, 'remix': 1.7,
    'stir': 0.8, 'stirred': 0.55, 'stirring': 0.6, 'mingle': 0.7,
    'blend': 0.3, 'blends': 0.3, 'blending': 0.3, 'blended': 0.55,
    'combination': 0.2, 'combinations': 0.12,
    '搅拌': 0.8, '拌': 0.9, '混': 2.3, '混合': 2.65,
}
FIX_FORMS = {
    'fix': 2.7, 'fixed': 1.35, 'fixing': 2.05, 'fixes': 2.4,
    'fixture': 0.65, 'fixtures': 1.05,
}


def lexical(token):
    word = token.strip().lstrip('_./\\([{-+*=,$:')
    w = word.lower()
    if w in MIXING:
        return MIXING[w]
    if w in FIX_FORMS:
        return FIX_FORMS[w]
    if w.endswith('prefix'):
        return 1.3
    if w in {'ixed', 'ixer', 'pixels', 'pixel', 'unix', 'linux'}:
        return {'ixed': 3.1, 'ixer': 2.5, 'pixel': 1.5, 'pixels': 1.1,
                'unix': 3.3, 'linux': 1.6}[w]
    if w == 'ix':
        if word != token.strip():
            return 3.2
        return 4.3 if token.startswith(' ') else 5.6
    # Short leading ix fragments also occur in inflected words.
    if w.startswith('ix'):
        return 2.4 if len(w) <= 4 else 1.6
    if w == 'x':
        if token.startswith(' '):
            return 0.70 if word == 'X' else 0.78
        return 0.90
    if not w.endswith('x'):
        return 0.0
    if w == 'six':
        return 0.76 if token.startswith(' ') and word.islower() else 1.6
    if w == 'atrix':
        return 0.2
    if w.endswith('ix'):
        return 3.8 if len(w) == 3 else (1.5 if len(w) <= 5 else 0.15)
    if w.endswith(('ex', 'box', 'max', 'tax', 'aux', 'prox')):
        return 0.05
    if len(w) == 2:
        return 0.65 if w == 'ax' else 1.2
    return 0.75 if len(w) <= 4 else 0.15


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    word = token.strip().lower()
    value = lexical(token)
    if word == 'of' and previous in {'mix', 'mixing', 'mixture'}:
        value += {'mix': 1.7, 'mixing': 1.05, 'mixture': 0.65}[previous]
    if word == 'up' and previous == 'mixed':
        value += 1.4
    return (document, word), float(value)

programs.luna:
"""Recognize x-bearing tokens, with a stronger response to capital X."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "X" in token:
        return None, 0.85
    if "x" in token:
        return None, 0.35
    return None, 0.0

programs.haiku:
"""Severity, symptom and diagnosis words in clinical text.

The component is positive on words that grade a condition (severe, mild, severity, baseline,
significant, markedly, worse, elevated, decreased, progression) and on symptom and diagnosis
words (symptom, fever, chest pain, dysfunction, ischemia, diagnosis). It is near zero on
generic disease nouns (disease, cancer, infection) and slightly negative on words from animal
studies (mice, rats). Its size grows in clinical text, so a running clinical-topic score,
decaying over the document, scales each word's value.
"""

READS = ()

SEVERITY = {"severe", "severity", "mild", "moderate", "marked", "markedly", "significant",
            "significantly", "serious", "critical", "acute", "bilateral", "progression",
            "progressive", "worse", "worsened", "poorer", "elevated", "decreased", "baseline",
            "prognosis", "relapse", "remission", "fatal", "benign", "rupture", "severely",
            "chronic", "poor", "wors", "worst", "intolerance", "suspected", "diagnosed"}
SYMPTOM = ("sympt", "diagnos", "dys", "ischem", "fever", "pain", "chest", "psychiatr",
           "pulmon", "renal", "cardi", "icu", "anxiety", "emia", "cough", "fatigue", "vomit",
           "nause", "headache", "complication")
SETTING = {"patient", "patients", "clinical", "clinically", "medical", "therapy", "therapies",
           "treatment", "serum", "dose", "history"}
ANIMAL = {"mice", "rats", "mouse", "rat"}

def _word(s):
    return s.strip().lower()

def _value(w):
    if w in SEVERITY:
        return 1.0
    if w.startswith(SYMPTOM):
        return 0.7
    if w in SETTING:
        return 0.4
    if w in ANIMAL:
        return -0.5
    return 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    topic = carry[0] if (carry is not None and carry[1] == doc) else 0.0
    value = _value(_word(prefix.token_strings[-1]))
    new_topic = 0.9 * topic + 0.1 * max(value, 0.0)
    return (new_topic, doc), value * (0.5 + topic)

"""Component layers.0.mlp.down_proj:3007 as a word-level rule.

What it responds to: the capitalised indefinite article "A" or "An" as a word of its own
(" A", "A" after a newline, after an opening bracket, dash or quote). It pushes the
activation strongly negative, more so at the start of a line and most of all when the
article opens a new document (right after <|endoftext|>). A bare "A" that continues an
all-capitals word (e.g. "...UM" + "A") is ignored. The capitalised word "The" pushes
weakly negative. The end-of-text token <|endoftext|> pushes it positive. Everything else
is about zero.
"""

READS = ()

EOT = "<|endoftext|>"
ARTICLES = {"A", "An", " A", " An"}
PUNCT_A = {"(A", "-A", ".A", "/A", "_A", '"A', "*A", "<A", "“A", "'A"}
THE_WORDS = {"The", " The"}


def is_caps_word(text):
    """True for an all-capitals word such as 'UM' or ' SO' (no lowercase letters)."""
    letters = text.strip()
    return len(letters) > 0 and letters.isalpha() and letters.isupper()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else EOT
    if token == EOT:
        return carry, 1.7
    if token in THE_WORDS:
        return carry, -1.6 if previous == EOT else -0.4
    if token in PUNCT_A:
        return carry, -5.0 if previous == EOT else -1.0
    if token in ARTICLES:
        if previous == EOT:
            return carry, -5.0
        if token in (" A", " An"):
            return carry, -0.9 if is_caps_word(previous) else -1.7
        if is_caps_word(previous):
            return carry, 0.0
        if previous.endswith("\n") or previous == "":
            return carry, -2.2
        return carry, -1.7
    return carry, 0.0

programs.luna:
"""Recognize end-of-text and a few capitalized English determiners.

The component is usually quiet, but it rises at the end-of-text marker and
falls on common capitalized article tokens. This small lexical rule captures
those conspicuous cases; it does not try to explain its weaker responses.
"""

READS = ()

END_OF_TEXT = "<|endoftext|>"
STRONG_ARTICLE = {"A", " A", "An", " An", "-A", "(A"}
THE = {"The", " The"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == END_OF_TEXT:
        return None, 1.73
    if token in STRONG_ARTICLE:
        return None, -1.65
    if token in THE:
        return None, -0.42
    return None, 0.0
